schemas.schema-01-systematic.prisma:
/// Discussion Board Configuration - This implements system-level configuration requirements from the requirements analysis documentation (see Non-Functional Requirements and Architecture). 
///
/// Business purpose: Stores global settings and operational flags for the board, such as feature enablement, thresholds, and display policies. Maintains 3NF by keeping system-wide settings atomically separate from user/content data. 
///
/// Usage: Queried on service initialization and periodically at runtime to control permissions, operational toggles, and thresholds (e.g., max attachment size, whether registration is open, maintenance announcements). Example: Disabling topic creation for maintenance.
///
/// Key relationships: None (standalone system table).
/// Special behaviors: One row per configuration type—enforced by unique index; can be extended as new features/flags are added. No direct business content association.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for configuration entry.
  id String @id @db.Uuid

  /// Configuration key - Implements requirement for identifying a specific configuration setting.
  ///
  /// Business meaning: System-wide feature name or flag, such as 'max_attachment_size', 'site_maintenance_mode'. Ensures normalization by atomically tracking each config. For example, 'topic_creation_enabled'. Unique per record.
  key String

  /// Configuration value - Implements requirement for flexible feature flag values.
  ///
  /// Business meaning: Actual config value, such as '10240', 'true', 'Welcome to the board!'. Keeps config values atomic and enables runtime updates. Example: setting a text maintenance message.
  /// Constraints: Can encode numeric or boolean values as string for flexible future extension.
  value String

  /// Description - Further explanation of this configuration setting.
  ///
  /// Business meaning: Helps admins understand the function/impact of the config. 3NF by being non-key attribute. Example: 'Enables or disables new topic creation.'
  description String?

  /// Creation timestamp. Implements requirement for auditable system configuration changes. Records when this configuration was created. 3NF-compliant.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp. Auditable adjustment tracking for config changes. For example, admin changing maintenance mode value.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([key])
  @@index([created_at])
}

/// Discussion Board Category - Implements requirement for organizing topics into top-level subjects (see Features and User Experience).
///
/// Business purpose: Tracks each discussion category (e.g., 'Politics', 'Economics', 'Announcements'), enabling topic organization, filtering, and permission separation. Maintains 3NF by keeping category attributes separate from content/posts. 
///
/// Usage: Used by threads and topics when assigning category. Example: 'create topic in category X'.
///
/// Key relationships: Referenced by topics (in another component).
/// Special behaviors: Enforces unique category codes. Supports description for category-specific guidance. Only system admins can add/remove.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for a discussion category.
  id String @id @db.Uuid

  /// Category code - Fulfills requirement for unique category reference across the board. Used in URLs, APIs, and permissions. Example: 'politics', 'economics'. Unique for quick lookup and routing. 3NF: atomic.
  /// Must be unique for each category.
  code String

  /// Category display name - Human-friendly name shown in UI. E.g., 'Political Discussion', 'Economics'. Supports localization as needed. 3NF-compliant.
  name String

  /// Category description - Explains subject focus or rules for this category. Shown in UI for member guidance; helps ensure relevant topic placement. Example: 'For all policy and political discussion.'
  description String?

  /// Sort order - Controls how categories are displayed in lists/menus. Implements requirement for customizable category order. Lower = higher on list. Atomic.
  /// Example: 1 = top/first category.
  sort_order Int @db.Integer

  /// Category active flag - Implements enable/disable logic for system or UI. Allows archiving categories without deletion. 3NF: atomic.
  /// Example: false = not available for new topics.
  is_active Boolean

  /// Creation timestamp. Auditable for category addition history.
  created_at DateTime @db.Timestamptz

  /// Update timestamp. Audit and list/display freshness tracking.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_category_permissions discussion_board_category_permissions[]
  discussion_board_topics               discussion_board_topics[]

  @@unique([code])
  @@index([sort_order])
  @@index([is_active])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion Board Category Permissions - Implements per-category permission requirements from the user role and permission analysis.
///
/// Business purpose: Manages access controls per category for each role type (admin, moderator, member, guest). Maps which roles can view/create/reply in each category. Maintains 3NF by separating permission sets from category data and actor/user data.
///
/// Usage: On each UI/API request to read or post in a category, checked for permission gates. Example: Only members may create topics in 'Announcements'.
///
/// Key relationships: References discussion_board_categories (category_id) and actor table (role_name). Enforces unique (category, role) permission sets.
/// Special behaviors: Record mutability reserved for admin users for operational control. Category deletion cascades to permissions.
///
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_category_permissions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique permission mapping entry.
  id String @id @db.Uuid

  /// Belonged category's {@link discussion_board_categories.id}. Category this set of permissions applies to.
  category_id String @db.Uuid

  /// Role name - Enforces per-role permissions for each category. One of: 'admin', 'moderator', 'member', 'guest'.
  /// Direct mapping to valid board roles. 3NF: atomic. Example: 'moderator'.
  role_name String

  /// View permission - Whether the role can view this category or not. Example: guests cannot view private categories. Atomic, not derived.
  /// Enables per-category access control.
  can_view Boolean

  /// Create topic permission - Whether role is allowed to create new topics in this category. Atomic, core permission.
  /// Used to prevent posting by members/guests as required.
  can_create_topic Boolean

  /// Reply permission - Whether the role can reply to topics in this category. Core granular posting control per role.
  can_reply Boolean

  /// Like permission - Whether the role can like/dislike content under this category. Used to gate interaction types for different roles.
  can_like Boolean

  /// Reporting permission - Whether users of this role can report/flag content in this category. E.g., guests typically not allowed.
  can_report Boolean

  /// Creation timestamp. Auditable permissions setup.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  category_permissions_category discussion_board_categories @relation(fields: [category_id], references: [id], onDelete: Cascade)

  @@unique([category_id, role_name])
  @@index([category_id])
  @@index([role_name])
}

schemas.schema-02-actors.prisma:
/// Administrators of the discussion board - This implements the core administrative role management requirement from the requirements analysis. Admins have the highest permissions and can manage users, content, and system configuration. Maintains 3NF by separating admin-specific identity from generic user profiles, allowing future support for role changes, and ensuring that only members with this assignment gain admin authority. For example, assigning 'admin' to a member enables platform management actions. Key relationships: links to user profile for identity, logs role change events, may coordinate with moderation logs. Special behaviors: Admin assignments are auditable, exclusive, and logged.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each admin assignment.
  id String @id @db.Uuid

  /// Linked user profile's {@link discussion_board_user_profiles.id}. Establishes which user has admin rights.
  discussion_board_user_profile_id String @db.Uuid

  /// Datetime when admin role assigned - Implements auditability and assignment traceability. Captures when a user becomes admin. Ensures role assignment normalization, example: Member promoted to admin on this timestamp. Cannot be null.
  assigned_at DateTime @db.Timestamptz

  /// Datetime when admin role was revoked - Implements role transition audit. Null if still active. Example: Admin role revoked during moderation, keeps role history normalized. Null = currently active; else terminated.
  revoked_at DateTime? @db.Timestamptz

  /// The assigning admin's {@link discussion_board_user_profiles.id} - Ensures traceability of who performed the assignment. For compliance and audit. Example: Assigned by another admin; not null on direct assignment. Behaves as a reference to actor performing change.
  assigned_by_user_profile_id String @db.Uuid

  //----
  // RELATIONS
  //----
  admin_user_profile discussion_board_user_profiles @relation(fields: [discussion_board_user_profile_id], references: [id], onDelete: Cascade)

  discussion_board_report_actions  discussion_board_report_actions[]
  discussion_board_moderation_logs discussion_board_moderation_logs[]
  discussion_board_flagged_content discussion_board_flagged_content[]

  @@unique([discussion_board_user_profile_id])
  @@index([assigned_by_user_profile_id])
  @@index([assigned_at])
}

/// Moderators of the discussion board - Implements the moderator role management requirement. Moderators oversee content, resolve disputes, but do not have full admin privileges. Maintains normalization by separating this role and allowing multiple users to be assigned as moderators, with history for assignment and revocation. For example, granting moderator to a member indicates they can edit/remove posts or manage reports. Key relationships: Links to user profiles; logs assignments. Special behaviors: Moderator assignments are auditable and support periodic review.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_moderators {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies the moderator assignment.
  id String @id @db.Uuid

  /// Moderator's user profile {@link discussion_board_user_profiles.id} - Links moderator to the user.
  discussion_board_user_profile_id String @db.Uuid

  /// Datetime moderator role assigned - Tracks when a user became a moderator; supports audit and normalization. Example: Member assigned moderator status at this timestamp. Cannot be null.
  assigned_at DateTime @db.Timestamptz

  /// Datetime moderator role was revoked; Null if still active. Supports role history normalization. For example: Moderation privileges revoked by admin, timestamped for compliance.
  revoked_at DateTime? @db.Timestamptz

  /// User profile that assigned moderator (admin or higher moderator) {@link discussion_board_user_profiles.id} - Ensures assignment is auditable and links to actor.
  assigned_by_user_profile_id String @db.Uuid

  //----
  // RELATIONS
  //----
  moderator_user_profile discussion_board_user_profiles @relation(fields: [discussion_board_user_profile_id], references: [id], onDelete: Cascade, map: "discussion_board_moderators_discussion_board_user_prof_51ab5951")

  discussion_board_report_actions  discussion_board_report_actions[]
  discussion_board_moderation_logs discussion_board_moderation_logs[]
  discussion_board_flagged_content discussion_board_flagged_content[]

  @@unique([discussion_board_user_profile_id], map: "discussion_board_moderators_discussion_board_user_prof_4e4bac74")
  @@index([assigned_by_user_profile_id])
  @@index([assigned_at])
}

/// Registered members of the discussion board - Implements core authenticated participant role. Members can create topics, posts, and interact with content. Maintains normalization by having member-specific entry, with relationships to user profiles, and not duplicating data. Example: Only users listed here can author new topics or posts. Key relationships: Linked to user profiles, referenced by posts/comments. Special behaviors: Can be linked to moderation actions and role upgrades/downgrades.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_members {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies the member assignment.
  id String @id @db.Uuid

  /// Associated user profile's {@link discussion_board_user_profiles.id} - Connects active member entity to user.
  discussion_board_user_profile_id String @db.Uuid

  /// Datetime user became a member - For onboarding and historical analysis. Strictly normalized: stores only assignment time. Example: Member joined at this date. Not null.
  joined_at DateTime @db.Timestamptz

  /// Datetime user left membership (if left); null if still active. Tracks exits for audit trails. For example: User opts out of platform.
  left_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  member_user_profile discussion_board_user_profiles @relation(fields: [discussion_board_user_profile_id], references: [id], onDelete: Cascade)

  discussion_board_topics_of_created_by_member_id     discussion_board_topics[]                    @relation("discussion_board_topics_of_created_by_member_id")
  discussion_board_topics_of_last_edited_by_member_id discussion_board_topics[]                    @relation("discussion_board_topics_of_last_edited_by_member_id")
  discussion_board_topic_snapshots                    discussion_board_topic_snapshots[]
  discussion_board_topic_subscriptions                discussion_board_topic_subscriptions[]
  discussion_board_posts                              discussion_board_posts[]
  discussion_board_post_snapshots                     discussion_board_post_snapshots[]
  discussion_board_comments                           discussion_board_comments[]
  discussion_board_post_attachments                   discussion_board_post_attachments[]
  discussion_board_post_likes                         discussion_board_post_likes[]
  discussion_board_reports                            discussion_board_reports[]
  discussion_board_notifications                      discussion_board_notifications[]
  discussion_board_user_notification_settings         discussion_board_user_notification_settings?

  @@unique([discussion_board_user_profile_id])
  @@index([joined_at])
}

/// Guests or unauthenticated users - Implements the role of view-only access for guests. Used to audit browse events or personalize some UI per session. Maintains normalization by keeping only atomic session or reference markers, not detailed identity. For example: A guest session is created for analytics, not for authoring. Key relationships: None mandatory, as guests don't own posts. Special behaviors: Entries may be ephemeral or deleted after session expiration.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_guests {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique for each guest session/actor.
  id String @id @db.Uuid

  /// Guest session identifier - Implements non-authenticated session tracking. Ensures normalization by not attributing to a user profile. For example: Tracks which anonymous visitor is browsing. Required, not null.
  session_id String

  /// Timestamp session created - For analytics and lifecycle management. Ensures guest session data can be expired appropriately. Not null.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([session_id])
  @@index([created_at])
}

/// User profiles on the board - Implements global user identity, fulfilling profile and authentication requirements. Each profile captures user info such as email, display name, and status, shared by all role-specific tables. Maintains separation from role assignments for strict normalization and identity reusability. For example: A user profile can be assigned roles as member, moderator, admin. Key relationships: Linked to all role tables; referenced by posts and actions site-wide. Special behaviors: Self-service management; deletion anonymizes sensitive data.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_user_profiles {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies the user profile.
  id String @id @db.Uuid

  /// User's unique email address - Implements identification and permission mapping. Must be unique for login and account management. Normalization: Does not duplicate in role tables. Example: alice@example.com. Required.
  email String

  /// User's chosen visible name - For in-platform display, can differ from email or legal name. Ensures separation of personal info and identity. Example: 'Alice W.' Required, not null.
  display_name String

  /// Timestamp when profile created - For history, onboarding, and audit. Maintains event normalization. E.g., profile registered at this date. Required.
  registered_at DateTime @db.Timestamptz

  /// Flag if profile is currently active. Implements global enable/disable for security and privacy. E.g., blocked or deleted users are set inactive but preserved for references. Not null.
  is_active Boolean

  //----
  // RELATIONS
  //----
  discussion_board_admins                                       discussion_board_admins?
  discussion_board_moderators                                   discussion_board_moderators?
  discussion_board_members                                      discussion_board_members?
  discussion_board_role_changes_of_target_user_profile_id       discussion_board_role_changes[]     @relation("discussion_board_role_changes_of_target_user_profile_id")
  discussion_board_role_changes_of_performed_by_user_profile_id discussion_board_role_changes[]     @relation("discussion_board_role_changes_of_performed_by_user_profile_id")
  discussion_board_audit_trails                                 discussion_board_audit_trails[]
  discussion_board_action_histories                             discussion_board_action_histories[]

  @@unique([email])
  @@index([is_active])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Role assignment and revocation events - Implements full audit trail for all role changes, as required for compliance and traceability. Each change records acting user, affected user, role type, and timestamp. Maintains strict 3NF: Each event is atomic, not duplicative. Example: Promoting a user to moderator is a new record specifying both actors and the action. Key relationships: links user profiles and role objects; referenced by admin review logs. Special behaviors: Immutable, one record per discrete role change event.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_role_changes {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies this role change event.
  id String @id @db.Uuid

  /// Affected user's {@link discussion_board_user_profiles.id} - Identifies user having role changed.
  target_user_profile_id String @db.Uuid

  /// Acting user's {@link discussion_board_user_profiles.id} - The admin/moderator who invoked the change. Required for traceability.
  performed_by_user_profile_id String @db.Uuid

  /// Role assigned or revoked (e.g., 'admin', 'moderator', 'member', 'guest') - Implements traceable action record. Only allowed values: admin, moderator, member, guest. Required. Ensures that only valid roles are logged.
  role_type String

  /// Type of role action ('assigned', 'revoked') - Implements event direction. Allowed values: assigned, revoked. Required. Example: assigned role of moderator, or revoked admin.
  action_type String

  /// Datetime when role change occurred - Precise audit. Not null. Example: 2025-07-28T07:52:36.294Z.
  timestamp DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  role_change_target_profile       discussion_board_user_profiles @relation("discussion_board_role_changes_of_target_user_profile_id", fields: [target_user_profile_id], references: [id], onDelete: Cascade)
  role_change_performed_by_profile discussion_board_user_profiles @relation("discussion_board_role_changes_of_performed_by_user_profile_id", fields: [performed_by_user_profile_id], references: [id], onDelete: Cascade)

  @@index([target_user_profile_id, timestamp], map: "discussion_board_role_changes_target_user_profile_id_t_42980e7a")
  @@index([performed_by_user_profile_id, timestamp], map: "discussion_board_role_changes_performed_by_user_profil_d6cfeca4")
  @@index([role_type])
  @@index([action_type])
}

schemas.schema-03-threads.prisma:
/// Discussion Topic master table – Implements the core requirement from: 'Topic Creation & Threads' (Features), RBAC (Roles & Permissions), and system content structure (Overview & Content Hierarchy). 
///
/// Business purpose: Each row represents a unique discussion topic under a specific category. Maintains 3NF by separating topics from posts and categories. For example, this will store the topic title, description, status, and metadata, while posts/replies are stored elsewhere. 
///
/// Key relationships: topic snapshots (for audit/versioning), subscriptions (user following), and references to categories and topic creator (user/member/admin). 
/// Special behaviors: Topics are editable (with version tracking), have status (open/closed/pinned), and are the parent entity for all thread activity.
///
/// @namespace Threads
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_topics {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the topic.
  id String @id @db.Uuid

  /// Belonged category's {@link discussion_board_categories.id}. Links topic to its category, enforcing the topic-categorization structure.
  discussion_board_category_id String @db.Uuid

  /// Creator's {@link discussion_board_members.id}. Identifies which member created the topic (could also be admin/moderator per RBAC).
  created_by_member_id String @db.Uuid

  /// Last editor's {@link discussion_board_members.id}. Who last updated the topic (if edited). May be nullable if never edited after creation.
  last_edited_by_member_id String? @db.Uuid

  /// Topic title – Implements 'title' aspect (requirement: every topic must have a unique, descriptive title). Clearly identifies the thread at a glance. Ensures normalization by storing only atomic string. Example: '2025 Economic Outlook Regulations'. Required.
  title String

  /// Topic description – Implements the 'description' requirement (detailed initial statement/problem/agenda for the topic). Preserves normal form by not duplicating post content. Example: 'This thread discusses the impact of fiscal measures on...' Required.
  description String

  /// Status flag – Implements topic workflow requirement. Business use: distinguishes open, closed, or pinned threads. Example values: 'open', 'closed', 'pinned' (enforced in application). Maintains normalization by not encoding logic in other tables.
  status String

  /// Timestamp for when topic was pinned (if applicable). Implements moderation/status history, fulfills auditability. Null if not pinned; updates only when pinned. Maintains atomicity/3NF. Example: 2025-07-28T09:00:00+09:00
  pinned_at DateTime? @db.Timestamptz

  /// Timestamp for when topic was closed (if applicable). Fulfills requirement for tracking closure. Null if topic is not closed. Maintains normalization by not aggregating closure data elsewhere.
  closed_at DateTime? @db.Timestamptz

  /// Creation timestamp – Implements audit trail and recency sorting. Essential for tracking and performance indexes. Required.
  created_at DateTime @db.Timestamptz

  /// Last updated timestamp – Enables tracking of edits/changes on the topic. Used for version control and audit log. Required.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_category discussion_board_categories @relation(fields: [discussion_board_category_id], references: [id], onDelete: Cascade)
  created_by_member         discussion_board_members    @relation("discussion_board_topics_of_created_by_member_id", fields: [created_by_member_id], references: [id], onDelete: Cascade)
  last_edited_by_member     discussion_board_members?   @relation("discussion_board_topics_of_last_edited_by_member_id", fields: [last_edited_by_member_id], references: [id], onDelete: Cascade)

  discussion_board_topic_snapshots     discussion_board_topic_snapshots[]
  discussion_board_topic_subscriptions discussion_board_topic_subscriptions[]
  discussion_board_posts               discussion_board_posts[]

  @@unique([discussion_board_category_id, title])
  @@index([last_edited_by_member_id])
  @@index([status])
  @@index([created_by_member_id, created_at])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Topic Snapshot/Audit table – Implements the audit trail and versioning requirement from 'Edit own topics/posts', 'Moderation', and compliance/auditability (Non-Functional, Section 2.5). 
///
/// Business purpose: Stores immutable historic versions of each topic for full traceability, rollback, and review by moderators/admins. Maintains 3NF by separating version data from the live topic. For example, when a topic is edited/pinned/closed, a new snapshot record is created.
///
/// Key relationships: Back-references the associated topic. Links to the editor and also the original creator.
/// Special behaviors: Snapshots are strictly append-only; no updates/deletes to preserve true historic record.
///
/// @namespace Threads
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_topic_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique snapshot identifier.
  id String @id @db.Uuid

  /// Parent topic's {@link discussion_board_topics.id}. Establishes many-to-one history relationship.
  discussion_board_topic_id String @db.Uuid

  /// Editor/member's {@link discussion_board_members.id}. Who performed the edit or action producing this snapshot. Required, always populated in audit trail.
  edited_by_member_id String @db.Uuid

  /// Topic title at the time of snapshot. Implements change tracking for titles (requirement: audit logs). Maintains 3NF by separating state history from live record.
  title String

  /// Topic description at the time of snapshot. Captures content as it was. Maintains normalization; no duplication outside snapshot/audit context.
  description String

  /// Topic status (open/closed/pinned) at time of snapshot. For rollback/history. Directly supports the versioning requirement.
  status String

  /// Pinned timestamp as of this snapshot. Maintains full timeline for audit and rollback. Null if not pinned at that revision.
  pinned_at DateTime? @db.Timestamptz

  /// Closed timestamp as of this snapshot. Maintains history for closure events. Null if not closed at that revision.
  closed_at DateTime? @db.Timestamptz

  /// Snapshot creation timestamp. Used for sorting historic timeline. Ensures atomic operation; not inherited from topic.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_topic discussion_board_topics  @relation(fields: [discussion_board_topic_id], references: [id], onDelete: Cascade)
  edited_by_member       discussion_board_members @relation(fields: [edited_by_member_id], references: [id], onDelete: Cascade)

  @@index([edited_by_member_id])
  @@index([discussion_board_topic_id, created_at], map: "discussion_board_topic_snapshots_discussion_board_topi_52e69387")
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Topic Subscription table – Implements personalized notifications and topic-following features from 'Notifications & Subscriptions', 'User Journeys', and 'Personalization'.
///
/// Business purpose: Records which member users (and possibly moderators/admins) have subscribed to which topics to receive notifications. Maintains full normalization by strictly representing the M:N user-topic subscription with no extraneous data. For example, each row is a single user's subscription to a given topic, supporting fast lookup for notification delivery.
///
/// Key relationships: Links member (subscriber) and the topic. May include a subscribe/unsubscribe timestamp for audit/history.
/// Special behaviors: Unique constraint prevents duplicate subscriptions to the same topic by the same member.
///
/// @namespace Threads
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_topic_subscriptions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the subscription row.
  id String @id @db.Uuid

  /// Subscribed topic's {@link discussion_board_topics.id}. Links subscription to a particular discussion topic.
  discussion_board_topic_id String @db.Uuid

  /// Subscribing member's {@link discussion_board_members.id}. Who is following the topic for notifications. Required.
  member_id String @db.Uuid

  /// Subscription timestamp (when user started following). Implements subscription history/notification logic.
  subscribed_at DateTime @db.Timestamptz

  /// Timestamp for when user unsubscribed, if applicable. Null if still subscribed. Maintains auditability without deleting data.
  unsubscribed_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_topic discussion_board_topics  @relation(fields: [discussion_board_topic_id], references: [id], onDelete: Cascade, map: "discussion_board_topic_subscriptions_discussion_board__71fc1cee")
  member                 discussion_board_members @relation(fields: [member_id], references: [id], onDelete: Cascade)

  @@unique([discussion_board_topic_id, member_id], map: "discussion_board_topic_subscriptions_discussion_board__6eebf0b7")
  @@index([member_id, subscribed_at], map: "discussion_board_topic_subscriptions_member_id_subscri_9f9b0f9c")
}

schemas.schema-04-posts.prisma:
/// Discussion Board Post - This implements the posting system requirement from the requirements document, enabling users to submit main topic content or replies. Posts are core user-generated content, backed by rich metadata and normalization. Maintains 3NF compliance by separating attachments, likes, and snapshots into their own models. For example, when a member creates a new reply in a topic, a 'discussion_board_posts' row is created, referencing the topic and user. Key relationships: links to topic, author (member/moderator/admin), snapshot history, attachments, likes. Special behaviors: Posts may be edited, deleted, or moderated; content versioning handled in snapshots.
///
/// @namespace Posts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_posts {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each post.
  id String @id @db.Uuid

  /// Associated topic's {@link discussion_board_topics.id}. Links the post to its parent discussion topic or thread.
  discussion_board_topic_id String @db.Uuid

  /// Author's {@link discussion_board_members.id}. Identifies the registered member who created the post; only one required per post.
  author_member_id String @db.Uuid

  /// Post title - Implements topic or main reply titling. Describes the subject of the post, shown in previews and search results. Only required for top-level/topic posts. Ensures normalization by storing in the main post entity. For example: 'What are the implications of new tax reforms?'
  title String?

  /// Post content/body - Implements the main content requirement. Holds all user-generated text, supporting rich formatting. Maintains normalization by keeping actual content atomic; attachments, likes, etc., separated. For example: 'The new tax code will likely increase investment...'.
  body String

  /// Soft deletion flag - Indicates if this post is deleted or hidden by moderation. Used for non-destructive removal, maintaining audit trails. Abides by normalization by not storing deleted status in snapshots. For example: true if deleted by a moderator.
  is_deleted Boolean

  /// Post creation datetime - Captures when the post was created. Ensures traceability and normalization. For example: 2025-07-28T09:52:36+09:00.
  created_at DateTime @db.Timestamptz

  /// Post last update datetime - Captures when the post was last modified. Updated on every edit. Maintains normalization for audit. For example: 2025-07-28T10:10:00+09:00.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  FK_discussion_board_posts_topic         discussion_board_topics  @relation(fields: [discussion_board_topic_id], references: [id], onDelete: Cascade)
  FK_discussion_board_posts_author_member discussion_board_members @relation(fields: [author_member_id], references: [id], onDelete: Cascade)

  discussion_board_post_snapshots   discussion_board_post_snapshots[]
  discussion_board_comments         discussion_board_comments[]
  discussion_board_post_attachments discussion_board_post_attachments[]
  discussion_board_post_likes       discussion_board_post_likes[]

  @@unique([discussion_board_topic_id, author_member_id, created_at], map: "discussion_board_posts_discussion_board_topic_id_autho_f2ecb532")
  @@index([author_member_id])
  @@index([created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Post Snapshot - This implements the versioning/audit requirement from the requirements analysis. Each snapshot records the full content, metadata, and author at a point in time whenever a post is edited. Maintains 3NF compliance by separating version history from the base post entity. For example, editing a post creates a 'discussion_board_post_snapshots' row referencing the post and author. Key relationships: references the post, author identity, and stores all edit versions for review/rollback. Special behaviors: Used for transparency, moderation, and rollback.
///
/// @namespace Posts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_post_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for this snapshot record.
  id String @id @db.Uuid

  /// Parent post's {@link discussion_board_posts.id}. Indicates which post this snapshot belongs to. Mandatory for tracking version history.
  discussion_board_post_id String @db.Uuid

  /// Snapshot author's {@link discussion_board_members.id}. The user who made this version edit; may differ from original author if moderator/admin edited.
  author_member_id String @db.Uuid

  /// Snapshot content body - Stores the full text of the post at the edit time. Ensures integrity by archiving true copy at each version. For example, before/after an edit.
  snapshot_body String

  /// Edit reason - Explains why the change was made, supporting moderation transparency. For example: 'Fixed typo', 'Removed prohibited content'.
  edit_reason String?

  /// Snapshot creation timestamp - When this version was saved.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  FK_discussion_board_post_snapshots_post          discussion_board_posts   @relation(fields: [discussion_board_post_id], references: [id], onDelete: Cascade)
  FK_discussion_board_post_snapshots_author_member discussion_board_members @relation(fields: [author_member_id], references: [id], onDelete: Cascade)

  @@unique([discussion_board_post_id, created_at], map: "discussion_board_post_snapshots_discussion_board_post__25f49178")
  @@index([author_member_id])
  @@index([created_at])
  @@index([snapshot_body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Post Comment - This fulfills the comment/in-line feedback requirement: allows users to add targeted comments to specific posts. Maintains normalization by keeping comments as a separate entity, referencing posts. For example, a reply written as a clarification or in-line discussion is a separate 'discussion_board_comments' row, attached to a post and user. Key relationships: references its post, parent comment (for threading), and commenter identity. Special behaviors: Supports nesting/threaded comments via parent_id, soft deletion for moderation.
///
/// @namespace Posts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies this comment.
  id String @id @db.Uuid

  /// Parent post's {@link discussion_board_posts.id}. Indicates which post this comment is attached to.
  discussion_board_post_id String @db.Uuid

  /// Commenter's {@link discussion_board_members.id}. Member who created this comment.
  author_member_id String @db.Uuid

  /// Parent comment's {@link discussion_board_comments.id}. Enables comment threading. Null for root comments.
  parent_id String? @db.Uuid

  /// Comment body - Implements main comment content. Holds atomic plain/rich text. Used in quick replies and clarifications.
  body String

  /// Soft deletion flag - Indicates if comment is removed from view while retaining for moderation/audit.
  is_deleted Boolean

  /// Comment creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Comment last edit timestamp.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  FK_discussion_board_comments_post          discussion_board_posts     @relation(fields: [discussion_board_post_id], references: [id], onDelete: Cascade)
  FK_discussion_board_comments_author_member discussion_board_members   @relation(fields: [author_member_id], references: [id], onDelete: Cascade)
  FK_discussion_board_comments_parent        discussion_board_comments? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive discussion_board_comments[] @relation("recursive")

  @@index([author_member_id])
  @@index([parent_id])
  @@index([discussion_board_post_id, created_at], map: "discussion_board_comments_discussion_board_post_id_cre_571d2d84")
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Post Attachment - Implements the file/image upload requirement. Allows users to attach documents, images, or media to posts without embedding content. Maintains normalization by storing attachments separately and only referencing posts. For example, uploading a PDF as evidence creates a 'discussion_board_post_attachments' row linked to a post and uploader. Key relationships: references the post and uploader identity. Special behaviors: Only certain file types/sizes allowed, supports post moderation on attachments.
///
/// @namespace Posts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_post_attachments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies attachment.
  id String @id @db.Uuid

  /// Parent post's {@link discussion_board_posts.id}. Indicates which post this attachment is linked to.
  discussion_board_post_id String @db.Uuid

  /// Uploader's {@link discussion_board_members.id}. Member who attached the file/image.
  uploader_member_id String @db.Uuid

  /// File URI - Stores where the attachment is located on disk, CDN, or object storage. Ensures atomized file reference. For example: 'https://cdn.site.com/files/file123.pdf'.
  file_uri String @db.VarChar(80000)

  /// Displayed file name - User/reader-friendly label for the attachment as shown in UI. Example: 'evidence_chart.pdf'.
  file_name String

  /// File size (bytes) - Stores the size in bytes for upload constraints and diagnostics.
  file_size Int @db.Integer

  /// MIME type - Specifies file type for correct rendering and filtering. Example: 'application/pdf', 'image/png'.
  mime_type String

  /// Soft deletion flag - Indicates attachment is hidden/restricted without purging from storage (for moderation and audit control).
  is_deleted Boolean

  /// Attachment creation timestamp.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  FK_discussion_board_post_attachments_post            discussion_board_posts   @relation(fields: [discussion_board_post_id], references: [id], onDelete: Cascade)
  FK_discussion_board_post_attachments_uploader_member discussion_board_members @relation(fields: [uploader_member_id], references: [id], onDelete: Cascade)

  @@unique([file_uri])
  @@index([uploader_member_id])
  @@index([discussion_board_post_id])
}

/// Post Like - Implements the like/dislike/vote requirement for post feedback and quality surfacing. Each record reflects a user's like/dislike on a post. Maintains normalization by making each like atomic and storing only user + post + flag. For example, when a member likes (or dislikes) a post, a row is created with post ID, member ID, is_like flag. Key relationships: references the post and the member who acted. Special behaviors: Each user can only like/dislike each post once; historical record kept for audit/moderation.
///
/// @namespace Posts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_post_likes {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for this like/dislike record.
  id String @id @db.Uuid

  /// Target post's {@link discussion_board_posts.id}. Post that received this feedback.
  discussion_board_post_id String @db.Uuid

  /// User's {@link discussion_board_members.id}. Member who liked/disliked the post.
  author_member_id String @db.Uuid

  /// Like or dislike flag - true if positive (like/upvote), false if negative (dislike/downvote). Satisfies per-post feedback normalization.
  is_like Boolean

  /// Timestamp of like/dislike action for audit and analytics.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  FK_discussion_board_post_likes_post          discussion_board_posts   @relation(fields: [discussion_board_post_id], references: [id], onDelete: Cascade)
  FK_discussion_board_post_likes_author_member discussion_board_members @relation(fields: [author_member_id], references: [id], onDelete: Cascade)

  @@unique([discussion_board_post_id, author_member_id], map: "discussion_board_post_likes_discussion_board_post_id_a_3d23e560")
  @@index([author_member_id])
  @@index([created_at])
}

schemas.schema-05-moderation.prisma:
/// Discussion Board Report Entity - Implements the requirement for recording all reports submitted by users regarding inappropriate, abusive, or rule-violating content (see moderation and safety requirements). 
///
/// This table is central for tracking user-initiated reports across posts, comments, or users. It holds key information about what is reported, by whom, when, and in what context. Maintains 3NF by ensuring each report instance is distinctly identified and all related data are atomic and non-redundant. For example, when a member flags a post for review, a new record is created here with references to the reported object and the report reason.
///
/// Key relationships: Each report links to the reporter (user), the content being reported (post, comment, etc.), and the chosen report reason. Tied to action and moderation logs via discussion_board_report_actions and discussion_board_moderation_logs for complete traceability.
/// Special behaviors: Soft deletion with audit trail, only authorized users (members and above) can create reports, guests cannot.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_reports {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each report. Implements database integrity and auditability.
  id String @id @db.Uuid

  /// Reporter user's {@link discussion_board_members.id} or equivalent. Links report to the account who initiated it. Ensures traceability and role compliance for moderation.
  reporter_id String @db.Uuid

  /// Report reason's {@link discussion_board_report_reasons.id}. Associates the report with a standardized reason, supporting analytics and moderation flow control.
  reason_id String @db.Uuid

  /// ID of the entity being reported. Supports diverse reportable content types (post, comment, etc.) by storing referred object's unique ID. Maintains normalization by handling just the pointer, not type/state data.
  reported_entity_id String @db.Uuid

  /// Type/category of the reported entity (e.g., post, comment, user). Implements requirement for generic moderation workflows. For example, 'post', 'comment', 'user'.
  reported_entity_type String

  /// Optional descriptive field where reporter can provide additional context. Maps to moderation requirement for 'reason details', maintaining normalization by being a pure comment.
  description String?

  /// Timestamp of report creation. Implements audit/logging requirement for full moderation traceability.
  created_at DateTime @db.Timestamptz

  /// Indicates if the report has been resolved/closed by moderation. Fulfills process management in moderation workflow. Atomic flag; all status history goes to action/log tables, not duplicated here.
  resolved Boolean

  //----
  // RELATIONS
  //----
  fk_discussion_board_reports_reporter discussion_board_members        @relation(fields: [reporter_id], references: [id], onDelete: Cascade)
  fk_discussion_board_reports_reason   discussion_board_report_reasons @relation(fields: [reason_id], references: [id], onDelete: Cascade)

  discussion_board_report_actions  discussion_board_report_actions[]
  discussion_board_moderation_logs discussion_board_moderation_logs[]

  @@index([reporter_id, created_at])
  @@index([reported_entity_id, reported_entity_type], map: "discussion_board_reports_reported_entity_id_reported_e_1d4250b0")
  @@index([reason_id])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion Board Report Reason Entity - Implements requirement for managing standardized reasons (types) for reporting content (see moderation and analytics requirements).
///
/// Purpose is to centralize all predefined (or admin-configurable) reasons available to users when reporting. Maintains highest normalization: one row per unique reason, eliminating redundant/dispersed texts. For example, "Spam", "Harassment", "Off-topic", etc.
///
/// Key Relationships: Referenced by multiple reports; never duplicated. Used for moderation analytics (e.g., most common report reasons over time).
/// Special behaviors: Soft-deletable (if past reports exist), but must not be removed if actively in use.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_report_reasons {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for report reason; enables safe reference from other tables.
  id String @id @db.Uuid

  /// Human-readable report reason or label (e.g., 'Spam', 'Harassment'). Implements requirement for user-facing standardized report reason selection. Atomic string, mapped by id.
  reason_text String

  /// Whether this report reason is currently selectable. Maintains normalization by decoupling reason identity from usage state. For example, old reasons can be deactivated without loss of reference integrity.
  active Boolean

  /// Timestamp when the reason was added. Supports analytics, reporting, and admin workflow analysis.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  discussion_board_reports discussion_board_reports[]

  @@unique([reason_text])
  @@index([active])
}

/// Discussion Board Report Action Entity - Implements the requirement for systematically recording action(s) taken in response to each reported item (see moderation workflow and audit compliance).
///
/// Each row represents a discrete action (e.g., 'content removed', 'user warned', 'report dismissed') taken by an admin or moderator as part of handling a report. Maintains strict 3NF by separating evented, atomic action records from reports and general activity logs. For instance, if a moderator resolves a report by removing a post, the action is logged here and linked to the report.
///
/// Key relationships: References both the original report and the acting admin/moderator. Ties to moderation log for full chain-of-custody.
/// Special behaviors: Immutable; once created, actions cannot be edited—only new actions may be appended.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_report_actions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the action event. Guarantees atomic, auditable action trails.
  id String @id @db.Uuid

  /// Target report {@link discussion_board_reports.id}. Links action event to originating report, ensuring full moderation traceability.
  report_id String @db.Uuid

  /// Admin actor's {@link discussion_board_admins.id}. The admin who performed the action, if applicable.
  admin_id String? @db.Uuid

  /// Moderator actor's {@link discussion_board_moderators.id}. The moderator who performed the action, if applicable.
  moderator_id String? @db.Uuid

  /// Action taken (e.g., 'remove_content', 'warn_user', 'close_report', 'reject_report'). Implements detailed auditing and process mapping. Ensures pure 3NF by storing only atomic action data.
  action_type String

  /// Optional field for additional context/details provided by moderator/admin. Fulfills transparency, appeals tracking, and secondary audit requirements. For example: 'Content restored after appeal.'
  action_notes String?

  /// Timestamp of action event creation, required for sequential and legal audit trails.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussion_board_report_actions_report          discussion_board_reports     @relation(fields: [report_id], references: [id], onDelete: Cascade)
  fk_discussion_board_report_actions_actor_admin     discussion_board_admins?     @relation(fields: [admin_id], references: [id], onDelete: Cascade)
  fk_discussion_board_report_actions_actor_moderator discussion_board_moderators? @relation(fields: [moderator_id], references: [id], onDelete: Cascade)

  @@index([report_id, created_at])
  @@index([admin_id])
  @@index([moderator_id])
  @@index([action_notes(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Discussion Board Moderation Log Entity - Implements logging requirement for all significant moderation events (see audit, compliance, and transparency requirements).
///
/// This table is the atomic ledger for all major actions performed by moderators/admins in the course of resolving reports—covers escalations, blockings, content restorations, etc. Enables post-hoc review, appeals process, and legal compliance. Maintains 3NF by only logging the event and pointer to relevant actor(s)/object(s).
///
/// Key relationships: Connects moderation actions to reports and actors. Complements report_actions for a full (non-redundant) audit trail.
/// Special behaviors: Immutable log; may only be appended to, never edited or deleted.
///
/// @namespace Moderation
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model discussion_board_moderation_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each log entry, guaranteeing a tamper-evident sequence.
  id String @id @db.Uuid

  /// If log relates to a report, pointer to the report {@link discussion_board_reports.id}. Enables cross-referencing reports and logs for compliance analysis.
  report_id String? @db.Uuid

  /// Admin actor's {@link discussion_board_admins.id}. The admin who performed the action, if applicable.
  admin_id String? @db.Uuid

  /// Moderator actor's {@link discussion_board_moderators.id}. The moderator who performed the action, if applicable.
  moderator_id String? @db.Uuid

  /// Nature/type of action being logged (e.g., 'block_user', 'remove_content', 'restore_content', 'escalate'). Implements analytic and legal reporting requirements. Maintains normalization by separating event type from other metadata.
  log_type String

  /// Optional detailed information surrounding the action (e.g., reason for escalation). Maintains normalization and pure 3NF by not duplicating atomic event data.
  details String?

  /// Timestamp of log creation, required for correct event sequencing and compliance.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_discussion_board_moderation_logs_report          discussion_board_reports?    @relation(fields: [report_id], references: [id], onDelete: Cascade)
