  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each flagged event; core element for all moderation pre-actions.
  id String @id @db.Uuid

  /// Admin actor's {@link discussion_board_admins.id}. Links the flagged event to the admin who initiated the flagging, if applicable.
