import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { Idiscussion_board_action_histories } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussion_board_action_histories";

/**
 * Validate admin can fetch a discussion board action history record by ID.
 *
 * This scenario tests the end-to-end admin flow:
 *
 * 1. Create a new action history entry with known data using the admin 'create'
 *    endpoint.
 * 2. Get that newly created entry back via the admin 'get by id' endpoint.
 * 3. Assert that all fields in the response match what was sent on creation
 *    (except those only set server-side, e.g., the generated id).
 * 4. Confirm the response type matches the schema and all necessary fields are
 *    present.
 * 5. Ensure correct access: only admins can perform these operations, and results
 *    reflect only schema-approved fields.
 */
export async function test_api_admin_discussion_board_actionHistories_test_get_action_history_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new action history log as admin with known values
  const createInput: Idiscussion_board_action_histories.ICreate = {
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "post_created",
    target_table: "discussion_board_posts",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    summary: "Initial post creation event for E2E test.",
    occurred_at: new Date().toISOString(),
  };
  const created: Idiscussion_board_action_histories =
    await api.functional.admin.discussion_board.actionHistories.create(
      connection,
      {
        body: createInput,
      },
    );
  typia.assert(created);

  // 2. Get the same log entry by id
  const fetched: Idiscussion_board_action_histories =
    await api.functional.admin.discussion_board.actionHistories.at(connection, {
      id: created.id,
    });
  typia.assert(fetched);

  // 3. Validate all fields (except id) match what was created
  TestValidator.equals("actor_id")(fetched.actor_id)(createInput.actor_id);
  TestValidator.equals("action_type")(fetched.action_type)(
    createInput.action_type,
  );
  TestValidator.equals("target_table")(fetched.target_table)(
    createInput.target_table,
  );
  TestValidator.equals("target_id")(fetched.target_id)(createInput.target_id);
  TestValidator.equals("summary")(fetched.summary ?? null)(
    createInput.summary ?? null,
  );
  TestValidator.equals("occurred_at")(fetched.occurred_at)(
    createInput.occurred_at,
  );

  // 4. Confirm schema compliance
  typia.assert<Idiscussion_board_action_histories>(fetched);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { Idiscussion_board_action_histories } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussion_board_action_histories";

/**
 * Test fetching a discussion board action history record using an invalid or
 * non-existent ID as admin.
 *
 * Business context: This test ensures that when an admin attempts to fetch an
 * action history entry with a UUID that does not exist in the system, the API
 * correctly handles the error scenario—returning a 404 or appropriate error
 * message—rather than returning data, leaking information, or producing
 * unhandled errors. This prevents resource enumeration and validates
 * boundary/error handling for secure resource access.
 *
 * Step-by-step process:
 *
 * 1. Generate a UUID that is not present in the system (simulate a truly
 *    non-existent action history ID).
 * 2. As an admin, attempt to fetch the action history record with this ID using
 *    the appropriate endpoint.
 * 3. Confirm the API throws an error (e.g., 404 not found), and no data is leaked.
 * 4. Use TestValidator.error to ensure an error is thrown, without inspecting the
 *    error message or shape (per guidelines).
 */
export async function test_api_admin_discussion_board_actionHistories_test_get_action_history_by_invalid_id(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID for a non-existent action history
  const invalidId = typia.random<string & tags.Format<"uuid">>();

  // 2 & 3. Confirm API returns an error (404 or equivalent) without leaking data
  await TestValidator.error(
    "should throw 404 or not found error when fetching non-existent action history",
  )(async () => {
    await api.functional.admin.discussion_board.actionHistories.at(connection, {
      id: invalidId,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { Idiscussion_board_action_histories } from "@ORGANIZATION/PROJECT-api/lib/structures/Idiscussion_board_action_histories";

/**
 * Ensure RBAC: Only admin users can access discussion board action history
 * details.
 *
 * This test validates that the GET /admin/discussion_board/actionHistories/{id}
 * endpoint strictly enforces admin-only access for audit trail retrieval. It
 * first creates a new action history entry as admin to guarantee a valid
 * target. The test then clears authentication to simulate a non-admin context
 * and tries to access the same entry, expecting a forbidden error due to RBAC
 * protections. This ensures sensitive event logs cannot be disclosed to
 * unauthorized users and confirms no data leakage occurs.
 *
 * Steps:
 *
 * 1. As admin, create an action history record for the discussion board audit log.
 * 2. Simulate a non-admin (unauthenticated) user by removing Authorization headers
 *    from the connection.
 * 3. Attempt to fetch the just-created record by its ID as non-admin.
 * 4. Confirm the endpoint denies access (error is thrown), proving RBAC is
 *    enforced.
 */
export async function test_api_admin_discussion_board_actionHistories_test_get_action_history_without_admin_permission(
  connection: api.IConnection,
) {
  // 1. Create an action history record as admin
  const actionHistory =
    await api.functional.admin.discussion_board.actionHistories.create(
      connection,
      {
        body: {
          actor_id: typia.random<string & tags.Format<"uuid">>(),
          action_type: "post_created",
          target_table: "discussion_board_posts",
          target_id: typia.random<string & tags.Format<"uuid">>(),
          summary: "Test - RBAC enforcement E2E scenario.",
          occurred_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        } satisfies Idiscussion_board_action_histories.ICreate,
      },
    );
  typia.assert(actionHistory);

  // 2. Remove authentication headers to simulate non-admin context
  const nonAdminConnection = {
    ...connection,
    headers: { ...connection.headers },
  };
  delete nonAdminConnection.headers["Authorization"];

  // 3. Attempt to fetch the entry as non-admin – expect RBAC denial
  await TestValidator.error(
    "non-admin forbidden from action history audit logs",
  )(async () => {
    await api.functional.admin.discussion_board.actionHistories.at(
      nonAdminConnection,
      {
        id: actionHistory.id,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationLog";
import type { IPageIDiscussionBoardModerationLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerationLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing discussion board moderation logs with pagination and
 * filtering (admin API)
 *
 * 이 테스트는 /admin/discussion_board/moderationLogs PATCH 엔드포인트의 동작을 검증합니다. 주요 검증
 * 포인트:
 *
 * - 여러 종류의 moderation log 데이터를 준비(의존 API로 기록 생성)
 * - 필터링(log_type, admin_id, report_id 등)과 페이지네이션 동작의 정확성
 * - 반환 필드가 스키마에 정의된 필드만 포함하는지 확인
 * - 조건에 일치하는 log 없음(empty result set)
 * - 복합 필터 조합/advanced search(다중 필드 및 다양한 조건)
 * - 필수 필드 누락 등 검증 오류 발생시 error
 *
 * 주요 절차 (Step-by-step):
 *
 * 1. 다양한 log_type/admin_id/report_id로 moderation log 데이터 복수 생성 (의존성)
 * 2. Admin_id 기준 필터로 리스트 조회 후, 반환 값이 모두 조건에 부합하며 스키마 필드만 포함되는지 검증
 * 3. 존재하지 않는 log_type 조건으로 조회 후 빈 리스트 반환 확인
 * 4. 복합 조건(restore_content 및 report_id) 조회 및 기대값 검증
 * 5. 필수 입력 누락 시 에러 처리 검증
 */
export async function test_api_admin_discussion_board_moderationLogs_test_list_moderation_logs_with_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. moderation log 테스트 데이터 생성 (의존: 다양한 log_type/admin)
  const admin1_id = typia.random<string & tags.Format<"uuid">>();
  const admin2_id = typia.random<string & tags.Format<"uuid">>();
  const report_id = typia.random<string & tags.Format<"uuid">>();
  const baseDate = new Date().toISOString();

  const logs = [
    await api.functional.admin.discussion_board.moderationLogs.create(
      connection,
      {
        body: {
          log_type: "block_user",
          admin_id: admin1_id,
          moderator_id: null,
          details: "Blocked repeated spam user.",
          report_id: null,
        } satisfies IDiscussionBoardModerationLog.ICreate,
      },
    ),
    await api.functional.admin.discussion_board.moderationLogs.create(
      connection,
      {
        body: {
          log_type: "block_user",
          admin_id: admin1_id,
          moderator_id: null,
          details: "IP block.",
          report_id: null,
        } satisfies IDiscussionBoardModerationLog.ICreate,
      },
    ),
    await api.functional.admin.discussion_board.moderationLogs.create(
      connection,
      {
        body: {
          log_type: "remove_content",
          admin_id: admin2_id,
          moderator_id: null,
          details: "Removed inappropriate post.",
          report_id: null,
        } satisfies IDiscussionBoardModerationLog.ICreate,
      },
    ),
    await api.functional.admin.discussion_board.moderationLogs.create(
      connection,
      {
        body: {
          log_type: "restore_content",
          admin_id: admin1_id,
          moderator_id: null,
          details: "Appeal approved.",
          report_id: report_id,
        } satisfies IDiscussionBoardModerationLog.ICreate,
      },
    ),
  ];
  logs.forEach((log) => typia.assert(log));

  // 2. admin_id 기준, log_type: block_user로 필터해서 리스트 조회; 모든 필드의 타입/값/스키마 필드 only 검증
  const list_block_user =
    await api.functional.admin.discussion_board.moderationLogs.index(
      connection,
      {
        body: {
          log_type: "block_user",
          admin_id: admin1_id,
          created_at: logs[0].created_at,
        },
      },
    );
  typia.assert(list_block_user);
  TestValidator.predicate("block_user+admin1만 조회됨")(
    list_block_user.data.every(
      (row) => row.log_type === "block_user" && row.admin_id === admin1_id,
    ),
  );
  // 반환되는 모든 row에서 스키마 field만 존재하는지 체크 (Object.keys)
  list_block_user.data.forEach((row) => {
    TestValidator.equals("스키마 필드만 존재")(Object.keys(row).sort())(
      [
        "id",
        "log_type",
        "admin_id",
        "moderator_id",
        "report_id",
        "details",
        "created_at",
      ].sort(),
    );
  });
  // 페이지네이션 객체 shape/type도 검증
  typia.assert(list_block_user.pagination);

  // 3. 존재하지 않는 log_type 조건으로 조회 (빈 결과)
  const empty =
    await api.functional.admin.discussion_board.moderationLogs.index(
      connection,
      {
        body: {
          log_type: "not_exist_type",
          created_at: baseDate,
        },
      },
    );
  typia.assert(empty);
  TestValidator.equals("존재하지 않은 log_type일 경우 empty list")(
    empty.data.length,
  )(0);

  // 4. 복합 필터(restore_content, report_id)
  const restore_page =
    await api.functional.admin.discussion_board.moderationLogs.index(
      connection,
      {
        body: {
          log_type: "restore_content",
          admin_id: admin1_id,
          report_id: report_id,
          created_at: logs[3].created_at,
        },
      },
    );
  typia.assert(restore_page);
  TestValidator.equals(
    "restore_content+report_id rows? 단 1개, report_id 일치",
  )(restore_page.data.length)(1);
  TestValidator.equals("restore_content+report_id row의 report_id 일치")(
    restore_page.data[0].report_id,
  )(report_id);

  // 5. 필수 입력(log_type) 누락 시 에러처리 (TS type level에서 커버되나 런타임 에러도 확인; 설계 불가시 omit)
  await TestValidator.error("log_type이 누락되면 에러 발생")(
    async () =>
      await api.functional.admin.discussion_board.moderationLogs.index(
        connection,
        {
          body: {
            // log_type: intentionally omitted
            admin_id: admin1_id,
            created_at: logs[0].created_at,
          } as any, // 불가피한 경우만 허용
        },
      ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
