  )(created.flagged_entity_type);
  TestValidator.equals("retrieved flag_type")(retrieved.flag_type)(
    created.flag_type,
  );
  TestValidator.equals("retrieved reason")(retrieved.reason)(created.reason);
  TestValidator.equals("retrieved cleared")(retrieved.cleared)(created.cleared);
