/**
 * 관리자(admin)가 토론 게시판 멤버 할당의 가입/탈퇴 시각을 수정하고, 비정상 사례(논리적 오류, 존재하지 않는 멤버)에 대한 반응도
 * 검증하는 테스트입니다.
 *
 * - 가입/탈퇴 일시를 변경할 수 있어야 하며, 정상 입력 시 반영됨을 확인합니다.
 * - Left_at(탈퇴)가 joined_at(가입)보다 이전이면 에러가 발생해야 합니다.
 * - 존재하지 않는 member id를 업데이트하려 하면 404가 나와야 합니다.
 *
 * 절차:
 *
 * 1. 테스트용 사용자 프로필 생성
 * 2. 멤버 할당 레코드 생성
 * 3. 가입/탈퇴 일시 정상 변경 및 반영 확인
 * 4. 탈퇴 시각 null 처리(현직 멤버 유지) 확인
 * 5. Left_at < joined_at일 때 오류반환 확인
 * 6. 없는 member id 업데이트 시 404 반환 확인
 */
export async function test_api_admin_discussion_board_members_test_admin_update_member_join_and_leave_times(
  connection: api.IConnection,
) {
  // 1. 테스트용 사용자 프로필 생성
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
          // registered_at은 자동 생성됨
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userProfile);

  // 2. 멤버 할당(assignment) 생성
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: typia.random<string & tags.Format<"date-time">>(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 3. 가입/탈퇴 일시를 새로운 임의 데이터로 정상 변경
  const newJoinedAt = typia.random<string & tags.Format<"date-time">>();
  const newLeftAt = typia.random<string & tags.Format<"date-time">>();
  const updated = await api.functional.admin.discussion_board.members.update(
    connection,
    {
      id: member.id,
      body: {
        joined_at: newJoinedAt,
        left_at: newLeftAt,
      } satisfies IDiscussionBoardMember.IUpdate,
    },
  );
  typia.assert(updated);
  TestValidator.equals("가입 시각 변경됨")(updated.joined_at)(newJoinedAt);
  TestValidator.equals("탈퇴 시각 변경됨")(updated.left_at)(newLeftAt);

  // 4. left_at을 null 처리(멤버 현직 유지) → null 반영
  const updated2 = await api.functional.admin.discussion_board.members.update(
    connection,
    {
      id: member.id,
      body: {
        joined_at: newJoinedAt,
        left_at: null,
      } satisfies IDiscussionBoardMember.IUpdate,
    },
  );
  typia.assert(updated2);
  TestValidator.equals("탈퇴 시각 null 처리")(updated2.left_at)(null);

  // 5. 비즈니스 오류: 탈퇴 시각이 가입 이전이면 에러 확인
  const impossibleJoinedAt = "2025-07-28T09:40:08.659+09:00";
  const impossibleLeftAt = "2023-01-01T00:00:00.000+09:00";
  await TestValidator.error("탈퇴 시각이 가입 이전이면 오류 발생")(async () => {
    await api.functional.admin.discussion_board.members.update(connection, {
      id: member.id,
      body: {
        joined_at: impossibleJoinedAt,
        left_at: impossibleLeftAt,
      } satisfies IDiscussionBoardMember.IUpdate,
    });
  });

  // 6. 존재하지 않는 멤버 id로 업데이트 시도(404 오류)
  await TestValidator.error("없는 member id 업데이트 시 404 반환")(async () => {
    await api.functional.admin.discussion_board.members.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        joined_at: typia.random<string & tags.Format<"date-time">>(),
        left_at: null,
      } satisfies IDiscussionBoardMember.IUpdate,
    });
  });
}

