 *    to ensure valid context and IDs for the role event.
 * 2. Requests creation of a role change event using valid values
 *    (target_user_profile_id, performed_by_user_profile_id, role_type,
 *    action_type, timestamp) and confirms that the resulting event is recorded
 *    correctly (fields match inputs, ID/timestamp are valid).
 * 3. Attempts multiple invalid input cases for robust error validation:
 *
 *    - Missing required fields
 *    - Invalid enum for role_type/action_type
 *    - Non-existent user profile IDs
 *    - Malformed timestamps Expects each to yield validation or integrity errors.
 * 4. Ensures all returned data is properly asserted (schema and content-wise), and
 *    confirms audit trail/field integrity for success.
 */
export async function test_api_admin_discussion_board_roleChanges_test_create_role_change_event_with_valid_and_invalid_input(
  connection: api.IConnection,
) {
  // 1. Create user profiles for the event: admin (actor) and target
  const adminProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: RandomGenerator.alphabets(8) + "@admin.com",
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(adminProfile);

  const targetProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: RandomGenerator.alphabets(8) + "@member.com",
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(targetProfile);

  // 2. Create a valid role change event
  const now = new Date().toISOString();
  const roleChangePayload = {
    target_user_profile_id: targetProfile.id,
    performed_by_user_profile_id: adminProfile.id,
    role_type: "moderator",
    action_type: "assigned",
    timestamp: now,
  } satisfies IDiscussionBoardRoleChange.ICreate;

  const created =
    await api.functional.admin.discussion_board.roleChanges.create(connection, {
      body: roleChangePayload,
    });
  typia.assert(created);
  TestValidator.equals("target_user_profile_id matches")(
    created.target_user_profile_id,
  )(targetProfile.id);
  TestValidator.equals("performed_by matches")(
    created.performed_by_user_profile_id,
  )(adminProfile.id);
  TestValidator.equals("role_type matches")(created.role_type)("moderator");
  TestValidator.equals("action_type matches")(created.action_type)("assigned");
  TestValidator.equals("timestamp matches")(created.timestamp)(now);

  // 3. Failures: missing required fields, invalid enums, non-existent IDs, malformed timestamps
  await TestValidator.error("missing required fields")(() =>
    api.functional.admin.discussion_board.roleChanges.create(connection, {
      body: {
        // missing performed_by_user_profile_id and action_type
        target_user_profile_id: targetProfile.id,
        role_type: "admin",
        timestamp: now,
      } as any, // test purposely omitted values (safe only here)
    }),
  );

  await TestValidator.error("invalid role_type enum")(() =>
    api.functional.admin.discussion_board.roleChanges.create(connection, {
      body: {
        target_user_profile_id: targetProfile.id,
        performed_by_user_profile_id: adminProfile.id,
        role_type: "superuser" as any,
        action_type: "assigned",
        timestamp: now,
      } as any,
    }),
  );

  await TestValidator.error("invalid action_type enum")(() =>
    api.functional.admin.discussion_board.roleChanges.create(connection, {
      body: {
        target_user_profile_id: targetProfile.id,
        performed_by_user_profile_id: adminProfile.id,
        role_type: "guest",
        action_type: "promoted" as any,
        timestamp: now,
      } as any,
    }),
  );

  await TestValidator.error("non-existent target_user_profile_id")(() =>
    api.functional.admin.discussion_board.roleChanges.create(connection, {
      body: {
        target_user_profile_id: typia.random<string & tags.Format<"uuid">>(),
        performed_by_user_profile_id: adminProfile.id,
        role_type: "guest",
        action_type: "revoked",
        timestamp: now,
      },
    }),
  );

  await TestValidator.error("non-existent performed_by_user_profile_id")(() =>
    api.functional.admin.discussion_board.roleChanges.create(connection, {
      body: {
        target_user_profile_id: targetProfile.id,
        performed_by_user_profile_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        role_type: "member",
        action_type: "assigned",
        timestamp: now,
      },
    }),
  );

  await TestValidator.error("malformed timestamp")(() =>
    api.functional.admin.discussion_board.roleChanges.create(connection, {
      body: {
        target_user_profile_id: targetProfile.id,
        performed_by_user_profile_id: adminProfile.id,
        role_type: "guest",
        action_type: "assigned",
        timestamp: "2025/07/28 10:30:00" as any,
      } as any,
    }),
  );
}

