 * endpoint works as expected:
 *
 * 1. Create a new post as a member.
 * 2. Edit the post to generate at least one snapshot (edit history/audit).
 * 3. (NOTE: There is no snapshot list/discover API; we lack a way to
 *    programmatically fetch the snapshot ID as would be ideal.)
 * 4. Retrieve a post snapshot by (a random) ID and assert its structure. In a real
 *    E2E, this would require a discoverable snapshot ID.
 *
 * This ensures that, as far as is possible with available APIs, the schema for
 * retrieving post snapshots is covered and the endpoint reliably returns a
 * correctly structured object for a valid ID.
 */
export async function test_api_discussion_board_test_get_post_snapshot_by_id_success(
  connection: api.IConnection,
) {
