/**
 * 테스트: 존재하지 않는 조건으로 댓글 검색 시 빈 결과가 반환되는지 검증한다.
 *
 * 이 테스트는 댓글 검색 API에서 실제로 존재하지 않는 author_member_id 또는 discussion_board_post_id를
 * 필터로 사용하여 요청할 때, data 배열이 빈 배열([])로 반환되고 pagination 메타데이터가 적절히 구성되어 있는지 검증한다.
 *
 * 1. 실제로 존재하지 않는 author_member_id로 검색
 *
 *    - 결과 data는 빈 배열이어야 하며, pagination 필드도 올바르게 생성되어야 한다.
 * 2. 존재하지 않는 discussion_board_post_id로 검색
 *
 *    - 결과 data는 빈 배열이어야 하며, pagination 필드도 올바르게 생성되어야 한다.
 *
 * 각 검색 케이스에서 pagination 객체의 current, pages 등 필드가 1 이상의 값을 가지는 등, 빈 결과일 때도 API의
 * 페이지네이션 스펙이 잘 지켜지는지 확인한다.
 */
export async function test_api_discussion_board_test_search_comments_with_empty_result(
  connection: api.IConnection,
) {
  // 1. 존재하지 않는 author_member_id로 댓글 검색
  const emptyByAuthor = await api.functional.discussion_board.comments.index(
    connection,
    {
      body: {
        author_member_id: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IDiscussionBoardComment.IRequest,
    },
  );
  typia.assert(emptyByAuthor);
  TestValidator.equals("author_member_id로 검색 결과 없음")(
    emptyByAuthor.data.length,
  )(0);
  // 빈 결과에도 pagination.current, pages는 1 이상이 나와야 한다 (페이지네이션 스펙 확인)
  TestValidator.predicate("pagination.pages는 1 이상")(
    emptyByAuthor.pagination.pages >= 1,
  );
  TestValidator.predicate("pagination.current는 1 이상")(
    emptyByAuthor.pagination.current >= 1,
  );

  // 2. 존재하지 않는 discussion_board_post_id로 댓글 검색
  const emptyByPost = await api.functional.discussion_board.comments.index(
    connection,
    {
      body: {
        discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IDiscussionBoardComment.IRequest,
    },
  );
  typia.assert(emptyByPost);
  TestValidator.equals("discussion_board_post_id로 검색 결과 없음")(
    emptyByPost.data.length,
  )(0);
  TestValidator.predicate("pagination.pages는 1 이상")(
    emptyByPost.pagination.pages >= 1,
  );
  TestValidator.predicate("pagination.current는 1 이상")(
    emptyByPost.pagination.current >= 1,
  );
}

