/**
 * 테스트: 댓글 작성자가 이미 존재하는 댓글의 본문 내용을 성공적으로 수정할 수 있어야 한다.
 *
 * 비즈니스 시나리오:
 *
 * - 인증된 사용자(댓글 작성자)가 자신의 댓글 본문을 정상적으로 수정할 수 있는지 검증한다.
 * - 댓글 업데이트 시 body(내용) 필드만 변경되고, id/author/post 등의 소유권 및 참조 정보는 변하지 않아야 한다.
 * - 수정 결과가 응답으로 정확하게 반영되는지, 그리고 모든 스키마 필드가 올바르게 세팅되어 있는지 검증한다.
 *
 * 주요 테스트 절차:
 *
 * 1. 댓글을 달 수 있는 게시글(post)을 생성한다.
 * 2. 해당 게시글에 댓글을 생성한다.
 * 3. 댓글 작성자가 자신의 댓글 본문을 수정한다.
 * 4. 수정된 댓글 응답에서 본문 내용이 바뀌었는지, 나머지 스키마 필드(작성자, 소프트 삭제 등)가 제대로 유지되는지 확인한다.
 * 5. 응답 형식 및 타입(validate) 검증.
 */
export async function test_api_my_discussion_board_comments_test_update_own_comment_body_success(
  connection: api.IConnection,
) {
  // 1. 댓글을 달 게시글 생성
  const topicId = typia.random<string & tags.Format<"uuid">>();
  const postCreate: IDiscussionBoardPost.ICreate = {
    discussion_board_topic_id: topicId,
    title: "테스트 게시글 제목",
