  // 2. 댓글 생성
  const commentCreate: IDiscussionBoardComment.ICreate = {
    discussion_board_post_id: post.id,
    body: "댓글의 원본 내용입니다.",
  };
  const comment = await api.functional.my.discussion_board.comments.create(
    connection,
    { body: commentCreate },
  );
  typia.assert(comment);

  // 3. 댓글 본문 수정
  const updatedBody = "댓글 수정된 본문 내용입니다.";
  const updatedComment =
    await api.functional.my.discussion_board.comments.update(connection, {
      id: comment.id,
      body: { body: updatedBody } satisfies IDiscussionBoardComment.IUpdate,
    });
  typia.assert(updatedComment);

  // 4. 수정된 댓글 확인: 본문만 변경, 나머지는 동일
  TestValidator.equals("댓글 id가 변경되지 않음")(updatedComment.id)(
    comment.id,
  );
  TestValidator.equals("게시글 참조 동일")(
    updatedComment.discussion_board_post_id,
  )(comment.discussion_board_post_id);
  TestValidator.equals("작성자 동일")(updatedComment.author_member_id)(
    comment.author_member_id,
  );
  TestValidator.equals("본문 변경됨")(updatedComment.body)(updatedBody);
  TestValidator.equals("soft deletion이 false로 유지됨")(
    updatedComment.is_deleted,
  )(false);
  TestValidator.equals("created_at은 유지")(updatedComment.created_at)(
    comment.created_at,
  );
  TestValidator.notEquals("updated_at은 내용 수정되면 변경됨")(
    updatedComment.updated_at,
  )(comment.updated_at);
}

