  TestValidator.equals("inactive-category name matches")(
    inactiveRetrieved.name,
  )(inactiveCategory.name);
  TestValidator.equals("inactive-category description matches")(
    inactiveRetrieved.description ?? null,
  )(inactiveCategory.description ?? null);
  TestValidator.equals("inactive-category sort_order matches")(
