import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardConfiguration";
import type { IPageDiscussionBoardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardConfiguration";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieving a paginated and filtered list of discussion board
 * configuration entries.
 *
 * This test will:
 *
 * 1. Request the first page of entries with a specific limit, order, and search
 *    string, then verify the returned list fits the request parameters.
 * 2. Request a later page and confirm paging behavior (possibly empty if not
 *    enough records present).
 * 3. Test with a filter string that matches no rows and verify the data array is
 *    empty and pagination metadata reflects zero records.
 * 4. Validate sorting order (asc/desc) and that returned configuration objects
 *    match the schema and, if possible, search string.
 * 5. Try different sort fields (e.g., key vs created_at) and order directions,
 *    confirm the first/last records change as expected.
 *
 * As the test cannot insert/delete/update configurations (endpoint is
 * read-only), it operates against whatever test fixture data exists. It must
 * assert on shape, correctness of paging and filtering, and handle the case of
 * zero results.
 */
export async function test_api_discussion_board_test_list_configurations_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Request first page with a limit, ascending sort by key, no search filter
  const firstPage = await api.functional.discussion_board.configurations.index(
    connection,
    {
      body: {
        page: 1,
        limit: 2,
        sort_field: "key",
        sort_order: "asc",
        search: null,
      },
    },
  );
  typia.assert(firstPage);
  TestValidator.predicate("firstPage.data not oversized")(
    firstPage.data.length <= 2,
  );
  if (firstPage.data.length > 0) {
    for (const config of firstPage.data) {
      typia.assert(config);
    }
    // Check sorting ascending by key
    for (let i = 1; i < firstPage.data.length; ++i) {
      TestValidator.predicate("key sorted asc")(
        firstPage.data[i - 1].key <= firstPage.data[i].key,
      );
    }
  }
  // 2. Request second page (to check paging)
  const secondPage = await api.functional.discussion_board.configurations.index(
    connection,
    {
      body: {
        page: 2,
        limit: 2,
        sort_field: "key",
        sort_order: "asc",
        search: null,
      },
    },
  );
  typia.assert(secondPage);
  TestValidator.equals("pagination page 2")(secondPage.pagination.current)(2);
  // 3. Request with a nonsense filter, expecting zero results
  const nonePage = await api.functional.discussion_board.configurations.index(
    connection,
    {
      body: {
        page: 1,
        limit: 5,
        search: "NO_SUCH_CONFIG_XYZ",
        sort_field: "key",
        sort_order: "asc",
      },
    },
  );
  typia.assert(nonePage);
  TestValidator.equals("no results")(nonePage.data.length)(0);
  TestValidator.equals("pagination no records")(nonePage.pagination.records)(0);
  // 4. Test sorting in opposite direction (descending)
  const descPage = await api.functional.discussion_board.configurations.index(
    connection,
    {
      body: {
        page: 1,
        limit: 2,
        sort_field: "key",
        sort_order: "desc",
        search: null,
      },
    },
  );
  typia.assert(descPage);
  if (descPage.data.length > 0) {
    for (const config of descPage.data) {
      typia.assert(config);
    }
    for (let i = 1; i < descPage.data.length; ++i) {
      TestValidator.predicate("key sorted desc")(
        descPage.data[i - 1].key >= descPage.data[i].key,
      );
    }
  }
  // 5. Try sorting by different field: created_at asc & then desc, compare first record changes
  const byCreatedAtAsc =
    await api.functional.discussion_board.configurations.index(connection, {
      body: {
        page: 1,
        limit: 1,
        sort_field: "created_at",
        sort_order: "asc",
      },
    });
  typia.assert(byCreatedAtAsc);
  const byCreatedAtDesc =
    await api.functional.discussion_board.configurations.index(connection, {
      body: {
        page: 1,
        limit: 1,
        sort_field: "created_at",
        sort_order: "desc",
      },
    });
  typia.assert(byCreatedAtDesc);
  if (byCreatedAtAsc.data.length === 1 && byCreatedAtDesc.data.length === 1) {
    // usually the id should be different for oldest/newest records
    TestValidator.notEquals("first record changes when order flips")(
      byCreatedAtAsc.data[0].id,
    )(byCreatedAtDesc.data[0].id);
  }
}

