import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardConfiguration";

/**
 * Validate update of configuration entry (value/description).
 *
 * This test ensures that configuration entries can be updated by their ID—
 * specifically, the 'value' and 'description' fields, as per system rules.
 *
 * Business Context:
 *
 * - Admins can modify existing configurations (value/description) but not the key
 *   or id.
 * - The test provides full coverage for the conventional admin edit scenario.
 *
 * Test Process:
 *
 * 1. Create a configuration entry for testing (save returned id)
 * 2. Update the entry's value and description using its id
 * 3. Verify the update operation succeeds and all changed fields are correct in
 *    response
 */
export async function test_api_admin_discussion_board_configurations_test_update_configuration_value_and_description(
  connection: api.IConnection,
) {
  // Step 1: Create a configuration entry
  const createInput = {
    key: `max_attachment_size_test_${Math.floor(Math.random() * 10000)}`,
    value: "10240",
    description: "첨부파일 업로드 최대 크기 (테스트용)",
  } satisfies IDiscussionBoardConfiguration.ICreate;

  const original =
    await api.functional.admin.discussion_board.configurations.create(
      connection,
      { body: createInput },
    );
  typia.assert(original);

  // Step 2: Update value and description (simulate a setting change)
  const updateInput = {
    value: (Number(original.value) + 2048).toString(),
    description: "업로드 최대 크기 값을 2048만큼 증가 (테스트수정)",
  } satisfies IDiscussionBoardConfiguration.IUpdate;

  const updated =
    await api.functional.admin.discussion_board.configurations.update(
      connection,
      { id: original.id, body: updateInput },
    );
  typia.assert(updated);

  // Step 3: Validate changes
  TestValidator.equals("update: id unchanged")(updated.id)(original.id);
  TestValidator.equals("update: key unchanged")(updated.key)(original.key);
  TestValidator.equals("update: value changed")(updated.value)(
    updateInput.value,
  );
  TestValidator.equals("update: description changed")(updated.description)(
    updateInput.description,
  );
  TestValidator.predicate("update: created_at/date-time format")(
    !!updated.created_at && typeof updated.created_at === "string",
  );
  TestValidator.predicate("update: updated_at/date-time format")(
    !!updated.updated_at && typeof updated.updated_at === "string",
  );
}

