    key: `test_key_${RandomGenerator.alphaNumeric(8)}`,
    value: RandomGenerator.alphaNumeric(16),
    description: "테스트 케이스용 구성 설명입니다.",
  } satisfies IDiscussionBoardConfiguration.ICreate;

  const configuration =
    await api.functional.admin.discussion_board.configurations.create(
      connection,
      { body: createInput },
    );
  typia.assert(configuration);

  // 2. 생성된 UUID로 삭제(하드 딜리트), 성공 시 반환값 없음
  await api.functional.admin.discussion_board.configurations.erase(connection, {
    id: configuration.id,
  });

  // 3. (불가) 삭제 후 엔트리 재조회 검증은 API 미제공 시 생략
  // 4. (불가) 삭제 감사 로그 검증은 별도 API 미제공 시 생략
}

