import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IPageIDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin-side paginated, filtered moderator assignments listing.
 *
 * This test ensures an admin can:
 *
 * - Retrieve paginated moderator assignments
 * - Filter by active and revoked status
 * - Filter/search by user profile ID
 * - Receive correct pagination metadata and assignment data
 *
 * Steps:
 *
 * 1. Create 3 user profiles (John, Jane, Bob)
 * 2. Assign all 3 as moderators
 * 3. Revoke Bob's moderator status (set revoked_at)
 * 4. List all moderators (no filter)
 * 5. Filter for only active moderators (is_active: true)
 * 6. Filter for only revoked moderators (is_active: false)
 * 7. Filter by Jane's user_profile_id
 * 8. List with pagination (limit=2, page=1)
 */
export async function test_api_admin_discussion_board_moderators_test_list_moderators_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Create three user profiles
  const johnProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: "John Moderator",
          is_active: true,
        },
      },
    );
  typia.assert(johnProfile);

  const janeProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: "Jane Moderator",
          is_active: true,
        },
      },
    );
  typia.assert(janeProfile);

  const bobProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: "Bob Moderator",
          is_active: true,
        },
      },
    );
  typia.assert(bobProfile);

  // Choose admin to assign moderators (use john as admin for simplicity)
  const assignerId = johnProfile.id;
  const now = new Date().toISOString();

  // 2. Assign as moderators
  const johnModerator =
    await api.functional.admin.discussion_board.moderators.create(connection, {
      body: {
        discussion_board_user_profile_id: johnProfile.id,
        assigned_at: now,
        assigned_by_user_profile_id: assignerId,
      },
    });
  typia.assert(johnModerator);

  const janeModerator =
    await api.functional.admin.discussion_board.moderators.create(connection, {
      body: {
        discussion_board_user_profile_id: janeProfile.id,
        assigned_at: now,
        assigned_by_user_profile_id: assignerId,
      },
    });
  typia.assert(janeModerator);

  const bobModerator =
    await api.functional.admin.discussion_board.moderators.create(connection, {
      body: {
        discussion_board_user_profile_id: bobProfile.id,
        assigned_at: now,
        assigned_by_user_profile_id: assignerId,
      },
    });
  typia.assert(bobModerator);

  // 3. Revoke Bob's moderator (set revoked_at)
  const revokedAt = new Date(Date.now() + 1000).toISOString();
  const bobRevoked =
    await api.functional.admin.discussion_board.moderators.update(connection, {
      id: bobModerator.id,
      body: {
        discussion_board_user_profile_id:
          bobModerator.discussion_board_user_profile_id,
        assigned_at: bobModerator.assigned_at,
        revoked_at: revokedAt,
        assigned_by_user_profile_id: assignerId,
      },
    });
  typia.assert(bobRevoked);

  // 4. List all moderators (no filter)
  const allResult =
    await api.functional.admin.discussion_board.moderators.index(connection, {
      body: {},
    });
  typia.assert(allResult);
  const allIds = allResult.data.map((m) => m.id);
  TestValidator.predicate("all moderators present")(
    allIds.includes(johnModerator.id) &&
      allIds.includes(janeModerator.id) &&
      allIds.includes(bobModerator.id),
  );

  // 5. List only active moderators (is_active: true)
  const activeResult =
    await api.functional.admin.discussion_board.moderators.index(connection, {
      body: { is_active: true },
    });
  typia.assert(activeResult);
  const activeIds = activeResult.data.map((m) => m.id);
  TestValidator.predicate("only active moderators returned")(
    activeIds.includes(johnModerator.id) &&
      activeIds.includes(janeModerator.id) &&
      !activeIds.includes(bobModerator.id),
  );

  // 6. List only revoked moderators (is_active: false)
  const revokedResult =
    await api.functional.admin.discussion_board.moderators.index(connection, {
      body: { is_active: false },
    });
  typia.assert(revokedResult);
  const revokedIds = revokedResult.data.map((m) => m.id);
  TestValidator.predicate("only revoked moderators returned")(
    revokedIds.length === 1 && revokedIds[0] === bobModerator.id,
  );

  // 7. Search by Jane's user profile id
  const janeResult =
    await api.functional.admin.discussion_board.moderators.index(connection, {
      body: { discussion_board_user_profile_id: janeProfile.id },
    });
  typia.assert(janeResult);
  TestValidator.predicate("filter by Jane's profile id")(
    janeResult.data.length === 1 &&
      janeResult.data[0].discussion_board_user_profile_id === janeProfile.id,
  );

  // 8. Paginate: limit = 2, page = 1
  const pagedResult =
    await api.functional.admin.discussion_board.moderators.index(connection, {
      body: { limit: 2, page: 1 },
    });
  typia.assert(pagedResult);
  TestValidator.equals("paginated moderator count")(pagedResult.data.length)(2);
  TestValidator.equals("pagination current page")(
    pagedResult.pagination.current,
  )(1);
  TestValidator.equals("pagination limit")(pagedResult.pagination.limit)(2);
  TestValidator.predicate("pagination total records")(
    pagedResult.pagination.records >= 3 && pagedResult.pagination.pages >= 2,
  );
}

