import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardCategoryPermission } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategoryPermission";

/**
 * Update selected boolean permission fields within a category permission
 * (admin-only) and validate that only those fields are changed.
 *
 * Business context:
 *
 * - Category-based permissions in a discussion board control role-based UI access
 *   and user interaction. Updates to these permissions must be strictly scoped
 *   and auditable to avoid accidental privilege escalation or data leaks.
 * - Explicitly tests that founded permission entries can be updated for specific
 *   boolean fields (e.g., can_reply, can_like) without changing unrelated
 *   fields or unauthorized columns.
 * - Tests the atomicity and auditability of such changes for RBAC safety.
 *
 * **Test steps:**
 *
 * 1. Create a new discussion board category (admin only)
 * 2. Create a category permission entry for role "member" in this category, with
 *    explicit permission booleans
 * 3. Update only can_reply=false and can_like=true via the update endpoint
 * 4. Verify only these fields changed, all other permission attributes remain
 *    identical
 * 5. Check that audit fields (created_at) remain
 * 6. Assert API type safety and business-level invariants throughout
 */
export async function test_api_admin_discussion_board_categoryPermissions_test_update_category_permission_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. Create a discussion board category
  const categoryInput: IDiscussionBoardCategory.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(2),
    description: RandomGenerator.paragraph()(1),
    sort_order: typia.random<number & tags.Type<"int32">>(),
    is_active: true,
  };
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: categoryInput,
    });
  typia.assert(category);

  // 2. Create a permission for this category as baseline
  const permInput: IDiscussionBoardCategoryPermission.ICreate = {
    category_id: category.id,
    role_name: "member",
    can_view: true,
    can_create_topic: true,
    can_reply: true,
    can_like: false,
    can_report: false,
  };
  const permission =
    await api.functional.admin.discussion_board.categoryPermissions.create(
      connection,
      { body: permInput },
    );
  typia.assert(permission);

  // 3. Update permission: change only can_reply and can_like
  const updateInput: IDiscussionBoardCategoryPermission.IUpdate = {
    can_reply: false,
    can_like: true,
  };
  const updated =
    await api.functional.admin.discussion_board.categoryPermissions.update(
      connection,
      { id: permission.id, body: updateInput },
    );
  typia.assert(updated);

  // 4. Validate atomicity: only selected fields changed
  TestValidator.equals("id unchanged")(updated.id)(permission.id);
  TestValidator.equals("category_id unchanged")(updated.category_id)(
    permission.category_id,
  );
  TestValidator.equals("role_name unchanged")(updated.role_name)(
    permission.role_name,
  );
  TestValidator.equals("can_view unchanged")(updated.can_view)(
    permission.can_view,
  );
  TestValidator.equals("can_create_topic unchanged")(updated.can_create_topic)(
    permission.can_create_topic,
  );
  TestValidator.notEquals("can_reply should change")(updated.can_reply)(
    permission.can_reply,
  );
