  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(12),
        name: RandomGenerator.paragraph()(1),
        description: RandomGenerator.paragraph()(1),
        sort_order: typia.random<number & tags.Type<"int32">>(),
        is_active: true,
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(category);

  // 2. Create a category permission (role: moderator)
  const permission =
    await api.functional.admin.discussion_board.categoryPermissions.create(
      connection,
      {
        body: {
          category_id: category.id,
          role_name: "moderator",
