  await api.functional.admin.discussion_board.categoryPermissions.erase(
    connection,
    {
      id: permission.id,
    },
  );

  // 4. Attempt deletion again: should throw error (record already removed)
  await TestValidator.error("Second delete returns not-found error")(
    async () => {
      await api.functional.admin.discussion_board.categoryPermissions.erase(
        connection,
        {
          id: permission.id,
        },
      );
    },
  );
}

