import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuditTrail } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditTrail";
import type { IPageIDiscussionBoardAuditTrail } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAuditTrail";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates the audit trail query with filters.
 *
 * This test ensures that the audit trail endpoint returns correctly filtered
 * results based on actor_id, action_type, target_table, and date filtering. It
 * first creates several audit trail records with controlled actor IDs, action
 * types, target tables, and timestamps. It then submits a filtered query for a
 * subset of those records. The test also checks that when using search filters
 * with no matching results, the API returns an empty page.
 *
 * Steps:
 *
 * 1. Create multiple audit trail records with varying actor_ids, action_types,
 *    target_tables, and created_at timestamps, including at least two with the
 *    same actor_id, action_type, and target_table and within a date range.
 * 2. Query the audit trail endpoint with filters for actor_id, action_type,
 *    target_table, and a date range containing only the two records above.
 *    Assert only those two are returned.
 * 3. Query with a date range and actor_id/action_type/target_table combination
 *    that matches no records; assert an empty result.
 */
export async function test_api_admin_discussion_board_auditTrails_test_list_audit_trails_with_date_and_actor_filters(
  connection: api.IConnection,
) {
  // 1. Create multiple audit trail records with known actor_id/action_type/target_table/date
  const known_actor_id = typia.random<string & tags.Format<"uuid">>();
  const unrelated_actor_id = typia.random<string & tags.Format<"uuid">>();
  const action_type = "moderation";
  const target_table = "discussion_board_posts";
  const unrelated_action_type = "delete";
  const unrelated_target_table = "discussion_board_comments";

  // Choose base dates (now, minus 1hr, plus 1hr)
  const now = new Date();
  const date1 = new Date(now.getTime() - 60 * 60 * 1000); // hour ago
  const date2 = new Date(now.getTime() - 30 * 60 * 1000); // 30 min ago
  const date3 = new Date(now.getTime() + 60 * 60 * 1000); // in 1 hr

  // Insert two target records (same actor/action/table in known window)
  const entryA = await api.functional.admin.discussion_board.auditTrails.create(
    connection,
    {
      body: {
        actor_id: known_actor_id,
        action_type,
        target_table,
        target_id: typia.random<string & tags.Format<"uuid">>(),
        details: "entryA-details",
        created_at: date1.toISOString(),
      },
    },
  );
  typia.assert(entryA);

  const entryB = await api.functional.admin.discussion_board.auditTrails.create(
    connection,
    {
      body: {
        actor_id: known_actor_id,
        action_type,
        target_table,
        target_id: typia.random<string & tags.Format<"uuid">>(),
        details: "entryB-details",
        created_at: date2.toISOString(),
      },
    },
  );
  typia.assert(entryB);

  // Insert unrelated records (different actor, type, table, date)
  const unrelated1 =
    await api.functional.admin.discussion_board.auditTrails.create(connection, {
      body: {
        actor_id: unrelated_actor_id,
        action_type: unrelated_action_type,
        target_table: unrelated_target_table,
        target_id: typia.random<string & tags.Format<"uuid">>(),
        details: "unrelated1",
        created_at: date3.toISOString(),
      },
    });
  typia.assert(unrelated1);

  // 2. Filtered query - should return only entryA/entryB
  const from = new Date(date1.getTime() - 1000); // just before date1
  const to = new Date(date2.getTime() + 1000); // just after date2
  const filtered =
    await api.functional.admin.discussion_board.auditTrails.index(connection, {
      body: {
        actor_id: known_actor_id,
        action_type,
        target_table,
        created_at_start: from.toISOString(),
        created_at_end: to.toISOString(),
      },
    });
  typia.assert(filtered);
  // Assert both records are present and only two returned
  TestValidator.equals("filtered count")(filtered.data.length)(2);
  const result_ids = filtered.data.map((r) => r.id).sort();
  const expected_ids = [entryA.id, entryB.id].sort();
  TestValidator.equals("ids match")(result_ids)(expected_ids);
  filtered.data.forEach((rec) => {
    TestValidator.equals("actor_id")(rec.actor_id)(known_actor_id);
    TestValidator.equals("action_type")(rec.action_type)(action_type);
    TestValidator.equals("target_table")(rec.target_table)(target_table);
    const created = new Date(rec.created_at);
    TestValidator.predicate("created_at in window")(
      created >= from && created <= to,
    );
  });

  // 3. Query with non-matching filters (empty expected)
  const emptyRes =
    await api.functional.admin.discussion_board.auditTrails.index(connection, {
      body: {
        actor_id: unrelated_actor_id,
        action_type: "nonsense_action_type",
        target_table: "nonexistent_table",
        created_at_start: now.toISOString(),
        created_at_end: new Date(now.getTime() + 5000).toISOString(),
      },
    });
  typia.assert(emptyRes);
  TestValidator.equals("empty data")(emptyRes.data.length)(0);
}

