import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuditTrail } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditTrail";

/**
 * E2E: Retrieve an audit trail entry by valid ID and verify all data fields.
 *
 * Validates that the audit trail lookup endpoint
 * (/admin/discussion_board/auditTrails/{id}) correctly retrieves a record
 * created via admin POST, returning all schema fields. The test ensures:
 *
 * 1. A new audit trail entry is created and its ID is saved.
 * 2. Fetching that ID returns the full entry with all original fields.
 * 3. All returned fields (ID, actor_id, action_type, target_table, target_id,
 *    details, created_at) match precisely the creation input.
 * 4. Fields that were set as null or omitted are returned as such.
 * 5. The endpoint works for both recent and old records.
 *
 * Steps:
 *
 * 1. Prepare and create a new audit trail entry (recent timestamp).
 * 2. Retrieve it via GET /admin/discussion_board/auditTrails/{id}.
 *
 *    - Assert ID, actor_id, action_type, target_table, target_id, details,
 *         created_at.
 * 3. Prepare and create a second audit trail entry with an old timestamp.
 * 4. Retrieve the old entry by ID and verify all fields are returned and match
 *    input.
 */
export async function test_api_admin_discussion_board_auditTrails_test_get_audit_trail_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a recent audit trail entry
  const now: string & tags.Format<"date-time"> =
    new Date().toISOString() as string & tags.Format<"date-time">;
  const baseInput: IDiscussionBoardAuditTrail.ICreate = {
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "update",
    target_table: "discussion_board_posts",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    details: "Changed the post title.",
    created_at: now,
  };
  const created =
    await api.functional.admin.discussion_board.auditTrails.create(connection, {
      body: baseInput,
    });
  typia.assert(created);

  // 2. Retrieve by ID and validate full data
  const found = await api.functional.admin.discussion_board.auditTrails.at(
    connection,
    { id: created.id },
  );
  typia.assert(found);
  TestValidator.equals("id matches")(found.id)(created.id);
  TestValidator.equals("actor_id matches")(found.actor_id)(baseInput.actor_id);
  TestValidator.equals("action_type matches")(found.action_type)(
    baseInput.action_type,
  );
  TestValidator.equals("target_table matches")(found.target_table)(
    baseInput.target_table,
  );
  TestValidator.equals("target_id matches")(found.target_id)(
    baseInput.target_id,
  );
  TestValidator.equals("details matches")(found.details)(baseInput.details);
  TestValidator.equals("created_at matches")(found.created_at)(
    baseInput.created_at,
  );

  // 3. Create an audit trail entry with an old timestamp
  const oldTimestamp: string & tags.Format<"date-time"> = new Date(
    Date.now() - 2 * 365 * 24 * 3600 * 1000,
  ).toISOString() as string & tags.Format<"date-time">;
  const oldInput: IDiscussionBoardAuditTrail.ICreate = {
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "delete",
    target_table: "discussion_board_posts",
    target_id: typia.random<string & tags.Format<"uuid">>(),
    details: null,
    created_at: oldTimestamp,
  };
  const createdOld =
    await api.functional.admin.discussion_board.auditTrails.create(connection, {
      body: oldInput,
    });
  typia.assert(createdOld);

  // 4. Retrieve and validate old record data
  const foundOld = await api.functional.admin.discussion_board.auditTrails.at(
    connection,
    { id: createdOld.id },
  );
  typia.assert(foundOld);
  TestValidator.equals("id matches")(foundOld.id)(createdOld.id);
  TestValidator.equals("actor_id matches")(foundOld.actor_id)(
    oldInput.actor_id,
  );
  TestValidator.equals("action_type matches")(foundOld.action_type)(
    oldInput.action_type,
  );
  TestValidator.equals("target_table matches")(foundOld.target_table)(
    oldInput.target_table,
  );
  TestValidator.equals("target_id matches")(foundOld.target_id)(
    oldInput.target_id,
  );
  TestValidator.equals("details matches")(foundOld.details)(oldInput.details);
  TestValidator.equals("created_at matches")(foundOld.created_at)(
    oldInput.created_at,
  );
}

