import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardReportReason } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReason";

/**
 * Validates that updating a report reason to duplicate another's reason_text is
 * rejected.
 *
 * This test checks the uniqueness constraint enforcement on the "reason_text"
 * field of moderation report reasons:
 *
 * 1. Create the first report reason (e.g., "Spam") with a given reason_text and
 *    set as active.
 * 2. Create the second report reason (e.g., "Harassment") with a different
 *    reason_text and also set as active.
 * 3. Attempt to update the second report reason's reason_text to the first
 *    reason's value, which would create a duplicate.
 * 4. Verify that the API throws an error (uniqueness violation) and the update
 *    does not proceed.
 * 5. Confirm that the second reason's original reason_text and values remain
 *    unchanged after rejection.
 */
export async function test_api_admin_discussion_board_reportReasons_test_update_report_reason_duplicate_reason_text(
  connection: api.IConnection,
) {
  // 1. Create the first report reason ("Spam")
  const reasonText1 = "Spam";
  const reason1 =
    await api.functional.admin.discussion_board.reportReasons.create(
      connection,
      {
        body: {
          reason_text: reasonText1,
          active: true,
        } satisfies IDiscussionBoardReportReason.ICreate,
      },
    );
  typia.assert(reason1);

  // 2. Create the second report reason ("Harassment")
  const reasonText2 = "Harassment";
  const reason2 =
    await api.functional.admin.discussion_board.reportReasons.create(
      connection,
      {
        body: {
          reason_text: reasonText2,
          active: true,
        } satisfies IDiscussionBoardReportReason.ICreate,
      },
    );
  typia.assert(reason2);

  // 3. Attempt to update the second reason's reason_text to match the first reason (should fail due to uniqueness constraint)
  await TestValidator.error("should reject duplicate reason_text")(async () => {
    await api.functional.admin.discussion_board.reportReasons.update(
      connection,
      {
        id: reason2.id,
        body: {
          reason_text: reasonText1,
        } satisfies IDiscussionBoardReportReason.IUpdate,
      },
    );
  });

  // 4. Confirm the second reason was not changed
  const reason2After =
    await api.functional.admin.discussion_board.reportReasons.update(
      connection,
      {
        id: reason2.id,
        body: {} satisfies IDiscussionBoardReportReason.IUpdate,
      },
    );
  typia.assert(reason2After);
  TestValidator.equals("reason_text unchanged")(reason2After.reason_text)(
    reasonText2,
  );
}

