 * accurate file metadata. The test simulates a real workflow involving
 * user/membership creation and file uploads, checking pagination integrity and
 * record accuracy.
 *
 * Steps:
 *
 * 1. Admin creates a user profile (uploader)
 * 2. Admin assigns the user as a board member
 * 3. Member creates a new post in a topic
 * 4. Member uploads several attachments to the post (exceeding one page, e.g., 12
 *    files)
 * 5. Query the /discussion_board/postAttachments endpoint with a specific
 *    page/limit and filter for the post
 * 6. Validate returned data: a) Page metadata is correct for the total number of
 *    attachments b) The attachments correspond to the correct files and post
 *    (metadata matches upload info) c) Pagination (count, offset, limited
 *    results per page) works correctly
 */
export async function test_api_discussion_board_test_list_post_attachments_with_pagination(
  connection: api.IConnection,
) {
  // 1. Admin creates a user profile
  const userProfileInput = {
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    is_active: true,
    registered_at: new Date().toISOString(),
  };
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      { body: userProfileInput },
    );
  typia.assert(userProfile);

  // 2. Admin assigns user as board member
  const memberInput = {
    discussion_board_user_profile_id: userProfile.id,
    joined_at: new Date().toISOString(),
  };
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    { body: memberInput },
  );
  typia.assert(member);

  // 3. Member creates a new post
  // Simulate member context (assume connection context switches to implement RBAC)
  const postInput = {
    discussion_board_topic_id: typia.random<string & tags.Format<"uuid">>(), // topic must exist in DB
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
  };
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    { body: postInput },
  );
  typia.assert(post);

  // 4. Member uploads 12 attachments to the post
  const NUM_ATTACHMENTS = 12;
  const attachmentInputs = ArrayUtil.repeat(NUM_ATTACHMENTS)(() => ({
    discussion_board_post_id: post.id,
    file_uri: `https://fileserver/${RandomGenerator.alphaNumeric(16)}`,
    file_name: RandomGenerator.alphaNumeric(10),
    file_size: typia.random<number & tags.Type<"int32">>(),
    mime_type: RandomGenerator.pick([
      "image/jpeg",
      "image/png",
      "application/pdf",
      "text/plain",
    ]),
  }));
  const attachments = [];
  for (const input of attachmentInputs) {
    const att = await api.functional.my.discussion_board.postAttachments.create(
      connection,
      { body: input },
    );
    typia.assert(att);
    attachments.push(att);
  }

  // 5. Query attachments via PATCH with pagination (page 1, limit 5)
  const PAGE = 1;
  const LIMIT = 5;
  const pagedResult =
    await api.functional.discussion_board.postAttachments.index(connection, {
      body: {
        discussion_board_post_id: post.id,
        page: PAGE,
        limit: LIMIT,
      },
    });
  typia.assert(pagedResult);

  // 6a. Validate page metadata
  TestValidator.equals("pagination.page")(pagedResult.pagination.current)(PAGE);
  TestValidator.equals("pagination.limit")(pagedResult.pagination.limit)(LIMIT);
  TestValidator.equals("total records")(pagedResult.pagination.records)(
    attachments.length,
  );
  TestValidator.predicate("paged data length")(
    pagedResult.data.length === LIMIT,
  );

  // 6b. Validate returned data matches uploads
  const expectedPageData = attachments.slice((PAGE - 1) * LIMIT, PAGE * LIMIT);
  for (let i = 0; i < pagedResult.data.length; ++i) {
    const returned = pagedResult.data[i];
    const expected = expectedPageData[i];
    TestValidator.equals(`attachment[${i}].file_name`)(returned.file_name)(
      expected.file_name,
    );
    TestValidator.equals(`attachment[${i}].file_uri`)(returned.file_uri)(
      expected.file_uri,
    );
    TestValidator.equals(`attachment[${i}].file_size`)(returned.file_size)(
      expected.file_size,
    );
    TestValidator.equals(`attachment[${i}].mime_type`)(returned.mime_type)(
      expected.mime_type,
    );
    TestValidator.equals(`attachment[${i}].discussion_board_post_id`)(
      returned.discussion_board_post_id,
    )(expected.discussion_board_post_id);
    TestValidator.equals(`attachment[${i}].uploader_member_id`)(
      returned.uploader_member_id,
    )(expected.uploader_member_id);
    TestValidator.equals(`attachment[${i}].is_deleted`)(returned.is_deleted)(
      false,
    );
  }
  // 6c. Validate that pagination is correct, with no duplicates
  const receivedIds = pagedResult.data.map((d) => d.id);
  TestValidator.equals("no duplicates in paged result")(
    new Set(receivedIds).size,
  )(pagedResult.data.length);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostAttachment";
import type { IPageDiscussionBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardPostAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate filtering/search for discussion board post attachments using file
 * name substring, is_deleted status, and uploader id filters.
 *
 * Business context:
 *
 * - Attachments are associated with posts, and each is uploaded by a member.
 * - Admin creates a user profile and assigns as a member first (dependencies).
 * - We create two posts, then upload several attachments with varied properties
 *   (file_name, mime_type, is_deleted).
 *
 * Steps:
 *
 * 1. Admin creates user profile.
 * 2. Admin assigns user profile as board member.
 * 3. Member creates two distinct posts.
 * 4. Member uploads several attachments across both posts, varying file_name and
 *    mime_type values; simulate a 'deleted' file in-memory for filter testing.
 * 5. Test file_name filtering: Query using file_name__contains substring, validate
 *    only matching attachments in response.
 * 6. Test is_deleted filtering: Query for is_deleted true and false, validate
 *    segregation.
 * 7. Test uploader_member_id filtering: Query by uploader id, expect only
 *    attachments uploaded by this member.
 * 8. Optionally, apply multiple filters in one request (intersection).
 * 9. Validate API returns only correct/expected records for each filter scenario.
 */
export async function test_api_discussion_board_test_list_post_attachments_with_filters(
  connection: api.IConnection,
) {
  // 1. Admin creates user profile
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        },
      },
    );
  typia.assert(userProfile);

  // 2. Admin assigns user as member
  const now = new Date().toISOString();
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: now,
      },
    },
  );
  typia.assert(member);

  // 3. Member creates two posts under random topic ids
  const topicId1 = typia.random<string & tags.Format<"uuid">>();
  const topicId2 = typia.random<string & tags.Format<"uuid">>();

  const post1 = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topicId1,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(post1);

  const post2 = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topicId2,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(post2);

  // 4. Member uploads attachments with varied file_name and mime_type
  const attachments = [
    // post1, normal attachment ("report1.pdf", application/pdf)
    await api.functional.my.discussion_board.postAttachments.create(
      connection,
      {
        body: {
          discussion_board_post_id: post1.id,
          file_uri: `https://cdn.example.com/files/report1.pdf`,
          file_name: "report1.pdf",
          file_size: 256000,
          mime_type: "application/pdf",
        },
      },
    ),
    // post1, deleted attachment ("to_delete.png", image/png)
    await api.functional.my.discussion_board.postAttachments.create(
      connection,
      {
        body: {
          discussion_board_post_id: post1.id,
          file_uri: `https://cdn.example.com/files/to_delete.png`,
          file_name: "to_delete.png",
          file_size: 400012,
          mime_type: "image/png",
        },
      },
    ),
    // post2, normal docx ("summary.docx", application/vnd.openxmlformats-officedocument.wordprocessingml.document)
    await api.functional.my.discussion_board.postAttachments.create(
      connection,
      {
        body: {
          discussion_board_post_id: post2.id,
          file_uri: `https://cdn.example.com/files/summary.docx`,
          file_name: "summary.docx",
          file_size: 12004,
          mime_type:
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        },
      },
    ),
    // post2, normal image ("photo2.png", image/png)
    await api.functional.my.discussion_board.postAttachments.create(
      connection,
      {
        body: {
          discussion_board_post_id: post2.id,
          file_uri: `https://cdn.example.com/files/photo2.png`,
          file_name: "photo2.png",
          file_size: 178900,
          mime_type: "image/png",
        },
      },
    ),
  ];
  for (const att of attachments) typia.assert(att);

  // Simulate soft-deleting the second attachment (cannot call API, so patch the object locally)
  attachments[1].is_deleted = true;

  // 5. Filter: file_name__contains substring ("report"); expect only report1.pdf
  {
    const resp = await api.functional.discussion_board.postAttachments.index(
      connection,
      {
        body: {
          file_name__contains: "report",
        },
      },
    );
    typia.assert(resp);
    TestValidator.equals("filter by file_name__contains")(
      resp.data.length === 1 && resp.data[0].file_name === "report1.pdf",
    )(true);
  }

  // 6. Filter: is_deleted true – should return only "to_delete.png"
  {
    const resp = await api.functional.discussion_board.postAttachments.index(
      connection,
      {
        body: {
          is_deleted: true,
        },
      },
    );
    typia.assert(resp);
    TestValidator.predicate("filter by is_deleted true")(
      resp.data.every((a) => a.is_deleted),
    );
  }
  // 6b. Filter: is_deleted false – should exclude "to_delete.png" (soft-deleted)
  {
    const resp = await api.functional.discussion_board.postAttachments.index(
      connection,
      {
        body: {
          is_deleted: false,
        },
      },
    );
    typia.assert(resp);
    TestValidator.predicate("filter by is_deleted false")(
      resp.data.every((a) => !a.is_deleted),
    );
  }
  // 7. Filter: uploader_member_id – expect all attachments match this member (all uploads by same user)
  {
    const resp = await api.functional.discussion_board.postAttachments.index(
      connection,
      {
        body: {
          uploader_member_id: member.id,
        },
      },
    );
    typia.assert(resp);
    TestValidator.predicate("filter by uploader_member_id")(
      resp.data.every((a) => a.uploader_member_id === member.id),
    );
  }
  // 8. Filter: intersection: post2, image/png
  {
    const resp = await api.functional.discussion_board.postAttachments.index(
      connection,
      {
        body: {
          discussion_board_post_id: post2.id,
          mime_type: "image/png",
        },
      },
    );
    typia.assert(resp);
    TestValidator.equals("intersection filter: post2 & image/png")(
      resp.data.length === 1 && resp.data[0].file_name === "photo2.png",
    )(true);
  }
  // 9. Pagination: limit 2
  {
    const resp = await api.functional.discussion_board.postAttachments.index(
      connection,
      {
        body: {
          limit: 2,
        },
      },
    );
    typia.assert(resp);
    TestValidator.equals("pagination limit 2")(resp.data.length)(2);
  }
}

