/**
 * Validate that a discussion board member can update the file_name and
 * mime_type on their own post attachment.
 *
 * This test simulates a member step-by-step workflow:
 *
 * 1. Admin creates a user profile for the attachment owner.
 * 2. Admin grants member status to the user profile with a join date.
 * 3. The member creates a post (requires an existing topic id).
 * 4. The member uploads an attachment to that post.
 * 5. The member updates the file_name and mime_type metadata fields of their own
 *    attachment.
 * 6. The response is checked to confirm that file_name and mime_type are updated
 *    as expected; other fields must remain unchanged.
 *
 * Edge case: Uses all real data dependencies; ensures update is scoped only to
 * allowed fields and user may not change immutable fields.
 */
export async function test_api_my_discussion_board_postAttachments_test_update_own_post_attachment_metadata_success(
  connection: api.IConnection,
) {
  // 1. Admin creates a user profile (for the member/attachment owner)
  const userProfileInput = {
    email: typia.random<string & tags.Format<"email">>(),
    display_name: RandomGenerator.name(),
    is_active: true,
    registered_at: new Date().toISOString(),
  } satisfies IDiscussionBoardUserProfile.ICreate;
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      { body: userProfileInput },
    );
  typia.assert(userProfile);

  // 2. Admin grants member status (membership assignment)
  const memberInput = {
    discussion_board_user_profile_id: userProfile.id,
    joined_at: new Date().toISOString(),
  } satisfies IDiscussionBoardMember.ICreate;
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    { body: memberInput },
  );
  typia.assert(member);

  // 3. Member creates a post (requires a topicId)
  // We must generate a valid topic ID, as topics are not in scope, use random UUID for simulation.
  const topicId = typia.random<string & tags.Format<"uuid">>();
  const postInput = {
    discussion_board_topic_id: topicId,
    title: RandomGenerator.paragraph()(),
    body: RandomGenerator.content()()(),
  } satisfies IDiscussionBoardPost.ICreate;
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    { body: postInput },
  );
  typia.assert(post);

  // 4. Member uploads an attachment
  const attachmentInput = {
    discussion_board_post_id: post.id,
    file_uri: `https://cdn.example.com/${typia.random<string>()}`,
    file_name: "testfile-v1.pdf",
    file_size: 1024,
    mime_type: "application/pdf",
  } satisfies IDiscussionBoardPostAttachment.ICreate;
  const attachment =
    await api.functional.my.discussion_board.postAttachments.create(
      connection,
      { body: attachmentInput },
    );
  typia.assert(attachment);

  // 5. Member updates file_name and mime_type of their own attachment
  const updateInput = {
    file_name: "testfile-v1-renamed.docx",
    mime_type:
      "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  } satisfies IDiscussionBoardPostAttachment.IUpdate;
  const updatedAttachment =
    await api.functional.my.discussion_board.postAttachments.update(
      connection,
      { id: attachment.id, body: updateInput },
    );
  typia.assert(updatedAttachment);

  // 6. Check that file_name and mime_type were updated and all other fields match original
  TestValidator.equals("attachment id")(updatedAttachment.id)(attachment.id);
  TestValidator.equals("file_name updated")(updatedAttachment.file_name)(
    updateInput.file_name,
  );
  TestValidator.equals("mime_type updated")(updatedAttachment.mime_type)(
    updateInput.mime_type,
  );
  TestValidator.equals("file_uri unchanged")(updatedAttachment.file_uri)(
    attachment.file_uri,
  );
  TestValidator.equals("file_size unchanged")(updatedAttachment.file_size)(
    attachment.file_size,
  );
  TestValidator.equals("is_deleted unchanged")(updatedAttachment.is_deleted)(
    attachment.is_deleted,
  );
  TestValidator.equals("post linkage unchanged")(
    updatedAttachment.discussion_board_post_id,
  )(attachment.discussion_board_post_id);
  TestValidator.equals("uploader_member_id unchanged")(
    updatedAttachment.uploader_member_id,
  )(attachment.uploader_member_id);
}

