import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostAttachment";

/**
 * 토론 게시판 글 첨부파일에 대한 소프트 삭제(논리 삭제) 비즈니스 흐름을 검증합니다.
 *
 * - 멤버가 자신이 업로드한 게시글 첨부파일을 논리적으로 삭제(soft delete)할 수 있음을 테스트합니다.
 * - 실제로 파일 데이터/메타 정보(파일 경로, 이름 등)는 여전히 남아 있고, 단지 is_deleted 필드만 true로 변경됨을 보장합니다.
 * - 요구된 전체 과정: 관리자→유저 프로필 생성→멤버 부여, 멤버 인증 컨텍스트로 게시글/첨부 업로드 후 직접 소유 첨부파일 논리 삭제
 *   시나리오입니다.
 *
 * [테스트 단계]
 *
 * 1. (관리자) 토론 게시판 사용자 프로필 생성
 * 2. (관리자) 해당 프로필을 멤버로 할당(즉시 활성화)
 * 3. (멤버 권한) 임의 토픽에 게시글 등록
 * 4. (멤버 권한) 방금 작성한 게시글에 첨부파일 등록
 * 5. (멤버 권한) 첨부파일 논리 삭제(Soft delete, is_deleted → true)
 * 6. (확인) 첨부파일 레코드가 실제로 남아 있고, is_deleted=true여야 하며 메타(MIME/파일명/경로 등)는 유지됨을 확인 (단,
 *    첨부파일 직접 조회 API가 없으므로, 삭제 API 이후 값 검증은 첨부파일 create 응답을 재사용하여 논리적 비교만 수행)
 */
export async function test_api_discussion_board_test_soft_delete_own_post_attachment_success(
  connection: api.IConnection,
) {
  // 1. (관리자) 유저 프로필 생성
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userProfile);

  // 2. (관리자) 해당 프로필을 멤버로 부여
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 3. (멤버 권한) 임의 토픽 UUID로 게시글 등록
  const topicId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: topicId,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);
  TestValidator.equals("글 작성자 확인")(post.author_member_id)(member.id);

  // 4. (멤버 권한) 게시글 첨부파일 등록
  const fileName = RandomGenerator.alphaNumeric(12);
  const fileUri = `https://cdn.example.com/files/${typia.random<string>()}`;
  const fileSize = typia.random<number & tags.Type<"int32">>();
  const mimeType = "application/pdf";

  const attachment =
    await api.functional.my.discussion_board.postAttachments.create(
      connection,
      {
        body: {
          discussion_board_post_id: post.id,
          file_uri: fileUri,
          file_name: fileName,
          file_size: fileSize,
          mime_type: mimeType,
        } satisfies IDiscussionBoardPostAttachment.ICreate,
      },
    );
  typia.assert(attachment);
  TestValidator.equals("첨부파일 업로더(멤버)")(attachment.uploader_member_id)(
    member.id,
  );
  TestValidator.equals("첨부파일 is_deleted 초기값 false")(
    attachment.is_deleted,
  )(false);
  TestValidator.equals("첨부파일 메타데이터 검사")(attachment.file_name)(
    fileName,
  );
  TestValidator.equals("첨부파일 용량 검사")(attachment.file_size)(fileSize);
  TestValidator.equals("첨부파일 mime 타입 검사")(attachment.mime_type)(
    mimeType,
  );
  TestValidator.equals("첨부파일 파일경로 검사")(attachment.file_uri)(fileUri);

  // 5. (멤버 권한) 첨부파일 소프트 삭제 실행
  await api.functional.my.discussion_board.postAttachments.erase(connection, {
    id: attachment.id,
  });
  // 6. 첨부파일 직접조회 API가 없으므로, 논리적으로 이전 응답 값 기준으로 soft delete 되었음만 검증
