import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPostLike";
import type { IPageDiscussionBoardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionBoardPostLike";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing and filtering discussion board post like/dislike records
 * with pagination
 *
 * This test validates the /discussion_board/postLikes PATCH endpoint that
 * searches and paginates post like/dislike (vote) records.
 *
 * Scenario outline:
 *
 * 1. Create multiple user profiles via admin (representing different members)
 * 2. Assign those users as discussion board members
 * 3. Each member creates posts in the discussion board
 * 4. Each member likes and dislikes a variety of posts (including their own and
 *    others')
 * 5. Call the /discussion_board/postLikes endpoint without filters to check all
 *    records are returned and pagination metadata is correct
 * 6. Apply various filters (by post id, by author_member_id, by is_like flag, by
 *    created_at range) and check returned records match criteria
 * 7. Test pagination (page, limit), including edge cases like page too large, very
 *    small/large limits
 * 8. Confirm total count (pagination.records) and returned data.length match
 *    expectations under different filters
 * 9. Confirm sorting order and field values in the returned objects are as
 *    expected
 * 10. Confirm that invalid or excessively large page number returns empty data or
 *     error response
 *
 * Validation and assertions:
 *
 * - Type and shape validation for all returned page/data objects
 * - Business logic: filter criteria, correct slicing for page/limit, correct
 *   total counts
 * - That created records appear and disappear as expected under filters
 * - Error handling for out-of-range pagination
 */
export async function test_api_discussion_board_test_list_post_likes_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // -------- Step 1: Create several user profiles (members) --------
  const NUM_MEMBERS = 3;
  const NUM_POSTS_PER_MEMBER = 2;
  const members: {
    profile: IDiscussionBoardUserProfile;
    member: IDiscussionBoardMember;
  }[] = [];
  for (let i = 0; i < NUM_MEMBERS; ++i) {
    const profile =
      await api.functional.admin.discussion_board.userProfiles.create(
        connection,
        {
          body: {
            email: typia.random<string & tags.Format<"email">>(),
            display_name: RandomGenerator.name(),
            is_active: true,
          } satisfies IDiscussionBoardUserProfile.ICreate,
        },
      );
    typia.assert(profile);

    const member = await api.functional.admin.discussion_board.members.create(
      connection,
      {
        body: {
          discussion_board_user_profile_id: profile.id,
          joined_at: new Date().toISOString(),
        } satisfies IDiscussionBoardMember.ICreate,
      },
    );
    typia.assert(member);
    members.push({ profile, member });
  }

  // -------- Step 2: Each member creates two posts --------
  // Topic id: can use arbitrary UUID per post (simulate distinct threads)
  const posts: {
    post: IDiscussionBoardPost;
    member: IDiscussionBoardMember;
  }[] = [];
  for (const { member, profile } of members) {
    for (let j = 0; j < NUM_POSTS_PER_MEMBER; ++j) {
      // Simulate login as this member: context left as is, as no login API is mapped
      const topic_id = typia.random<string & tags.Format<"uuid">>();
      const post = await api.functional.my.discussion_board.posts.create(
        connection,
        {
          body: {
            discussion_board_topic_id: topic_id,
            title: RandomGenerator.paragraph()(),
            body: RandomGenerator.content()()(),
          } satisfies IDiscussionBoardPost.ICreate,
        },
      );
      typia.assert(post);
      posts.push({ post, member });
    }
  }

  // -------- Step 3: Each member likes/dislikes a set of posts --------
  // pattern: each member likes the first post of each other member, dislikes the second, including own posts
  type MemberPostLikeInfo = {
    like: IDiscussionBoardPostLike;
    is_like: boolean;
    member: IDiscussionBoardMember;
    post: IDiscussionBoardPost;
  };
  const likeRecords: MemberPostLikeInfo[] = [];
  for (const { member } of members) {
    for (let idx = 0; idx < posts.length; ++idx) {
      const is_like = idx % 2 === 0;
      const { post } = posts[idx];
      const like = await api.functional.my.discussion_board.postLikes.create(
        connection,
        {
          body: {
            discussion_board_post_id: post.id,
            is_like,
          } satisfies IDiscussionBoardPostLike.ICreate,
        },
      );
      typia.assert(like);
      likeRecords.push({ like, is_like, member, post });
    }
  }

  // Total possible likes/dislikes = NUM_MEMBERS * NUM_POSTS_PER_MEMBER * NUM_MEMBERS
  const EXPECTED_TOTAL = NUM_MEMBERS * NUM_POSTS_PER_MEMBER * NUM_MEMBERS;

  // -------- Step 4: Query all likes/dislikes, check totals and paging --------
  const resultAll = await api.functional.discussion_board.postLikes.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(resultAll);
  TestValidator.equals("pagination.records matches expected count")(
    resultAll.pagination.records,
  )(EXPECTED_TOTAL);
  // Default limit should be 100, so data.length matches total when under limit
  TestValidator.equals("data length matches expected total")(
    resultAll.data.length,
  )(EXPECTED_TOTAL);

  // -------- Step 5: Test filtering by post id (should only return relevant records) --------
  const byPost = posts[0];
  const filterByPost = await api.functional.discussion_board.postLikes.index(
    connection,
    {
      body: {
        discussion_board_post_id: byPost.post.id,
      },
    },
  );
  typia.assert(filterByPost);
  TestValidator.predicate("all returned have matching post id")(
    filterByPost.data.every(
      (rec) => rec.discussion_board_post_id === byPost.post.id,
    ),
  );
  TestValidator.equals("count matches expected")(
    filterByPost.pagination.records,
  )(NUM_MEMBERS);

  // -------- Step 6: Test filtering by author_member_id --------
  const byMember = members[0].member;
  const filterByMember = await api.functional.discussion_board.postLikes.index(
    connection,
    {
      body: {
        author_member_id: byMember.id,
      },
    },
  );
  typia.assert(filterByMember);
  TestValidator.predicate("all returned have matching author member id")(
    filterByMember.data.every((rec) => rec.author_member_id === byMember.id),
  );

  // -------- Step 7: Test filtering by is_like (only likes == true) --------
  const filterByIsLike = await api.functional.discussion_board.postLikes.index(
    connection,
    {
      body: {
        is_like: true,
      },
    },
  );
  typia.assert(filterByIsLike);
  TestValidator.predicate("all are is_like true")(
    filterByIsLike.data.every((rec) => rec.is_like === true),
  );

  // -------- Step 8: Test filtering by created_at_from/created_at_to --------
  // Use min/max from created like records
  const sortedLikes = [...likeRecords].sort((a, b) =>
    a.like.created_at.localeCompare(b.like.created_at),
  );
  const earliest = sortedLikes[0].like.created_at;
  const mid = sortedLikes[Math.floor(sortedLikes.length / 2)].like.created_at;
  const latest = sortedLikes[sortedLikes.length - 1].like.created_at;
  // Filter by from
  const filterFrom = await api.functional.discussion_board.postLikes.index(
    connection,
    {
      body: {
        created_at_from: mid,
      },
    },
  );
  typia.assert(filterFrom);
  TestValidator.predicate("all created_at >= mid")(
    filterFrom.data.every((rec) => rec.created_at >= mid),
  );
  // Filter by to
  const filterTo = await api.functional.discussion_board.postLikes.index(
    connection,
    {
      body: {
        created_at_to: mid,
      },
    },
  );
  typia.assert(filterTo);
  TestValidator.predicate("all created_at <= mid")(
    filterTo.data.every((rec) => rec.created_at <= mid),
  );

  // -------- Step 9: Pagination tests: use page/limit --------
  // First page (limit 2):
  const page1 = await api.functional.discussion_board.postLikes.index(
    connection,
    {
      body: {
        page: 1,
        limit: 2,
      },
    },
  );
  typia.assert(page1);
  TestValidator.equals("pagination.current is 1")(page1.pagination.current)(1);
  TestValidator.equals("limit matches")(page1.pagination.limit)(2);
  TestValidator.equals("data.length matches limit or total")(page1.data.length)(
    Math.min(2, EXPECTED_TOTAL),
  );
  // Second page:
  const page2 = await api.functional.discussion_board.postLikes.index(
    connection,
    {
      body: {
        page: 2,
        limit: 2,
      },
    },
  );
  typia.assert(page2);
  TestValidator.equals("pagination.current is 2")(page2.pagination.current)(2);
  // Data should be different than page 1:
  TestValidator.notEquals("page 1 and page 2 different")(
    page1.data.map((l) => l.id).join(),
  )(page2.data.map((l) => l.id).join());

  // Last page: page beyond the last (should be empty data)
  const overPage = Math.ceil(EXPECTED_TOTAL / 2) + 1000;
  const lastPage = await api.functional.discussion_board.postLikes.index(
    connection,
    {
      body: {
        page: overPage,
        limit: 2,
      },
    },
  );
  typia.assert(lastPage);
  TestValidator.equals("empty data for over-page")(lastPage.data.length)(0);
}

