  // 2. Create user profile
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.alphabets(8),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userProfile);

  // 3. Assign user as discussion board member
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 4. Set category to inactive
  const updatedCategory =
    await api.functional.admin.discussion_board.categories.update(connection, {
      id: category.id,
      body: {
        name: category.name,
        description: category.description,
        sort_order: category.sort_order,
        is_active: false,
      } satisfies IDiscussionBoardCategory.IUpdate,
    });
  typia.assert(updatedCategory);
  TestValidator.equals("category inactive")(false)(updatedCategory.is_active);

  // 5. Attempt to create topic as this member in the inactive category
