  const member1 = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile1.id,
        joined_at: joined_at1,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member1);

  const member2 = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile2.id,
        joined_at: joined_at2,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member2);

  // 3. Create discussion category
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph()(),
        sort_order: 1,
        is_active: true,
      } satisfies IDiscussionBoardCategory.ICreate,
    });
  typia.assert(category);

  // --- Simulate switching authentication to the first member ---
  // 4. Create a topic as the first member
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(),
        description: RandomGenerator.content()()(),
