 * unsubscribed_at (setting it to null). The test verifies DB state consistency
 * after each action, particularly the correct handling of unsubscribed_at and
 * membership linkage.
 *
 * Steps:
 *
 * 1. Create admin user profile.
 * 2. Assign membership to user.
 * 3. Create category for new topic.
 * 4. As the member, create a topic in the new category.
 * 5. Member subscribes to the topic.
 * 6. Unsubscribe by updating topic subscription (set unsubscribed_at).
 * 7. Re-subscribe by again updating topic subscription (set unsubscribed_at=null).
 * 8. Verify resulting subscription: unsubscribed_at=null, topic id, and member id
 *    are correct.
 *
 * (Notification dispatch confirmation is out of E2E scope; verified by DB
 * state.)
 */
export async function test_api_discussion_board_topicSubscriptions_test_update_topic_subscription_resubscribe_after_unsubscribe(
  connection: api.IConnection,
) {
  // 1. Create user profile
  const email = typia.random<string & tags.Format<"email">>();
