  // 8. Confirm the returned record has unsubscribed_at = null, and topic/member match
  TestValidator.equals("resubscribed unsubscribed_at=null")(
    resubscribed.unsubscribed_at,
  )(null);
  TestValidator.equals("topic id matches")(
    resubscribed.discussion_board_topic_id,
  )(topic.id);
  TestValidator.equals("member id matches")(resubscribed.member_id)(
    subscription.member_id,
  );
}

