import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardTopicSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopicSubscription";
import type { IVoidResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoidResponse";

/**
 * Validates hard deletion of a topic subscription by its owner (the member).
 *
 * This test ensures that a member can subscribe to a topic, then hard-delete
 * the subscription by its ID, and that the deletion is permanent. No soft
 * delete is present in schema – the entity is fully erased from the system.
 *
 * Steps:
 *
 * 1. Admin creates a user profile for the member
 * 2. Admin assigns the user profile as a discussion board member
 * 3. Admin creates a category for topics
 * 4. (With member authentication) The member creates a discussion topic in the
 *    category
 * 5. The member subscribes to their own topic, producing a subscription ID
 * 6. The member deletes the topic subscription by ID (hard delete)
 * 7. Verify that repeated deletion attempts throw an error (subscription no longer
 *    exists)
 */
export async function test_api_discussion_board_topicSubscriptions_test_delete_own_topic_subscription_by_id(
  connection: api.IConnection,
) {
  // 1. Admin: create user profile for the member
  const userEmail = typia.random<string & tags.Format<"email">>();
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: userEmail,
          display_name: RandomGenerator.name(),
          is_active: true,
          registered_at: new Date().toISOString(),
        },
      },
    );
  typia.assert(userProfile);

  // 2. Admin: assign the profile as a board member
  const joinedAt = new Date().toISOString();
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: joinedAt,
      },
    },
  );
  typia.assert(member);

  // 3. Admin: create a forum category
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphabets(8),
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph()(),
        sort_order: 1,
        is_active: true,
      },
    });
  typia.assert(category);

  // 4. (Member context) Create a discussion topic in this category
  // (Assume test harness can use/connect as this member; otherwise, this is a logical step)
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        title: "Test Topic " + RandomGenerator.alphabets(4),
        description: RandomGenerator.paragraph()(),
        status: "open",
        pinned_at: null,
        closed_at: null,
      },
    },
  );
  typia.assert(topic);

  // 5. Member subscribes to the topic
  const subscription =
    await api.functional.my.discussion_board.topicSubscriptions.create(
      connection,
      {
        body: {
          discussion_board_topic_id: topic.id,
        },
      },
    );
  typia.assert(subscription);

  // 6. Member deletes their own topic subscription (hard delete)
  const response =
    await api.functional.my.discussion_board.topicSubscriptions.erase(
      connection,
      {
        id: subscription.id,
      },
    );
  typia.assert(response);

  // 7. Further deletion attempts for this subscription ID should throw (not found)
  await TestValidator.error("Second deletion attempt returns error")(() =>
    api.functional.my.discussion_board.topicSubscriptions.erase(connection, {
      id: subscription.id,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IVoidResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoidResponse";

/**
 * Test attempting to delete a topic subscription with an invalid or
 * non-existent ID.
 *
 * This case ensures the system properly rejects deletion requests for topic
 * subscriptions that do not exist, returning an error response instead of
 * performing a deletion. No side effects or unexpected data changes should
 * occur.
 *
 * Steps:
 *
 * 1. Generate a random UUID (which does not correspond to any existing
 *    subscription).
 * 2. Attempt to call the delete endpoint for this non-existent topic subscription
 *    ID.
 * 3. Verify that the system responds with an error (e.g., not found) and does not
 *    indicate success.
 */
export async function test_api_my_test_delete_topic_subscription_by_id_that_does_not_exist(
  connection: api.IConnection,
) {
  // 1. Generate a random (non-existent) topic subscription ID
  const nonExistentId = typia.random<string & tags.Format<"uuid">>();

  // 2. Attempt to delete the non-existent subscription and expect an error response
  await TestValidator.error(
    "Should return error for non-existent topic subscription",
  )(async () => {
    await api.functional.my.discussion_board.topicSubscriptions.erase(
      connection,
      {
        id: nonExistentId,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
