import type { IVoidResponse } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoidResponse";

/**
 * Validate that a member cannot delete another member's topic subscription.
 *
 * This test ensures that a topic subscription, which is created by one member,
 * cannot be deleted by a second, unrelated member. This validates access
 * control enforcement for subscription deletion operations.
 *
 * Steps:
 *
 * 1. Create two user profiles (user1 and user2) via admin API.
 * 2. Assign both as members via admin API (member1 and member2).
 * 3. Create a category for the topic context.
 * 4. As member1, create a topic in the category.
 * 5. As member1, subscribe to that topic.
 * 6. As member2, attempt to delete member1's subscription and confirm denial
 *    (permission error).
 */
export async function test_api_discussion_board_test_delete_topic_subscription_that_belongs_to_another_member(
  connection: api.IConnection,
) {
  // 1. Create two user profiles (user1, user2)
  const user1 = await api.functional.admin.discussion_board.userProfiles.create(
    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        is_active: true,
      },
    },
  );
  typia.assert(user1);

  const user2 = await api.functional.admin.discussion_board.userProfiles.create(
    connection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        is_active: true,
      },
    },
  );
  typia.assert(user2);

  // 2. Assign both as members
  const now = new Date().toISOString();
  const member1 = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: user1.id,
        joined_at: now,
      },
    },
  );
  typia.assert(member1);

  const member2 = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: user2.id,
        joined_at: now,
      },
    },
  );
  typia.assert(member2);

  // 3. Create a category
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphabets(8),
        name: RandomGenerator.paragraph()(3),
        description: RandomGenerator.paragraph()(3),
        sort_order: 1,
        is_active: true,
      },
    });
  typia.assert(category);

  // 4. As member1, create a topic (assume member1 session where needed)
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(2),
        description: RandomGenerator.paragraph()(5),
        status: "open",
      },
    },
  );
  typia.assert(topic);

  // 5. As member1, subscribe to topic
  const subscription =
    await api.functional.my.discussion_board.topicSubscriptions.create(
      connection,
      {
        body: {
          discussion_board_topic_id: topic.id,
        },
      },
    );
  typia.assert(subscription);

  // 6. As member2, attempt to delete member1's subscription (should be denied)
  await TestValidator.error(
    "cannot delete another member's topic subscription",
  )(async () => {
    await api.functional.my.discussion_board.topicSubscriptions.erase(
      connection,
      {
        id: subscription.id,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the posts list API for basic pagination and correct ordering.
 *
 * This test verifies that the discussion board's post listing endpoint
 * correctly supports pagination (page/limit) and returns items in expected
 * order. It does so by:
 *
 * 1. Creating (admin) several user profiles to simulate users.
 * 2. Registering each as a board member (required to write posts/topics).
 * 3. Creating at least one discussion category (required for a topic).
 * 4. Having members create multiple topics under the discussion category.
 * 5. Populating the topics with multiple posts by the various members.
 * 6. Querying the list endpoint (PATCH /discussion_board/posts) with specific
 *    pagination parameters (page, limit), and checking: (a) the number of
 *    returned posts per page matches limit, (b) posts are returned in insertion
 *    order.
 * 7. Optionally, repeating with different parameters for additional pagination
 *    validation.
 *
 * This ensures both data correctness and compliance to query behaviors on the
 * posts listing endpoint.
 */
export async function test_api_discussion_board_test_list_posts_with_basic_pagination_and_sorting(
  connection: api.IConnection,
) {
  // 1. Create several user profiles
  const userCount = 3;
  const userProfiles: IDiscussionBoardUserProfile[] = [];
  for (let i = 0; i < userCount; ++i) {
    const profile =
      await api.functional.admin.discussion_board.userProfiles.create(
        connection,
        {
          body: {
            email: typia.random<string & tags.Format<"email">>(),
            display_name: RandomGenerator.name(),
            is_active: true,
            registered_at: new Date().toISOString(),
          },
        },
      );
    typia.assert(profile);
    userProfiles.push(profile);
  }

  // 2. Register each user as a discussion board member
  const members: IDiscussionBoardMember[] = [];
  for (const userProfile of userProfiles) {
    const member = await api.functional.admin.discussion_board.members.create(
      connection,
      {
        body: {
          discussion_board_user_profile_id: userProfile.id,
          joined_at: new Date().toISOString(),
        },
      },
    );
    typia.assert(member);
    members.push(member);
  }

  // 3. Create a category for the discussion board
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphabets(8),
        name: "Test Category",
        description: "For E2E Test",
        sort_order: 1,
        is_active: true,
      },
    });
  typia.assert(category);

  // 4. Members create topics in the created category
  const topics: IDiscussionBoardTopic[] = [];
  for (const member of members) {
    // (Simulate login or context switch as needed - assume connection context updates member auth)
    const topic = await api.functional.my.discussion_board.topics.create(
      connection,
      {
        body: {
          discussion_board_category_id: category.id,
          title: `Topic from ${member.id}`,
          description: RandomGenerator.paragraph()(),
          status: "open",
          pinned_at: null,
          closed_at: null,
        },
      },
    );
    typia.assert(topic);
    topics.push(topic);
  }

  // 5. Members create posts in the topics
  // For simplicity: let each member write a post in each topic (userCount * userCount posts)
  const posts: IDiscussionBoardPost[] = [];
  for (const topic of topics) {
    for (const member of members) {
      // (Assume context switch/auth sufficient to let the member post)
      const post = await api.functional.my.discussion_board.posts.create(
        connection,
        {
          body: {
            discussion_board_topic_id: topic.id,
            title: `Post by ${member.id} in topic ${topic.id}`,
            body: RandomGenerator.content()()(),
          },
        },
      );
      typia.assert(post);
      posts.push(post);
    }
  }

  // 6. Query the posts list endpoint with pagination (page=1, limit=4)
  const page = 1;
  const limit = 4;
  const list = await api.functional.discussion_board.posts.index(connection, {
    body: {
      page,
      limit,
      // Can further filter, e.g., by topic, but fetch all posts for this test
    },
  });
  typia.assert(list);

  // 7. Validate: response contains 'limit' records, and all are in our created posts array
  TestValidator.equals("pagination.limit")(list.pagination.limit)(limit);
  TestValidator.equals("pagination.current")(list.pagination.current)(page);
  TestValidator.predicate(`page data size matches limit or total count`)(
    list.data.length === limit || list.data.length === posts.length,
  );

  // 8. Check page 2 and ensure non-overlap with page 1 records if enough posts were created
  if (posts.length > limit) {
    const list2 = await api.functional.discussion_board.posts.index(
      connection,
      {
        body: { page: 2, limit },
      },
    );
    typia.assert(list2);
    // IDs from page 1 and page 2 should be disjoint if enough records
    const page1Ids = new Set(list.data.map((p) => p.id));
    const page2Ids = new Set(list2.data.map((p) => p.id));
    TestValidator.predicate("no overlap between page 1 and 2")(
      Array.from(page1Ids).every((id) => !page2Ids.has(id)),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for discussion board posts listing with topic and author filters.
 *
 * This test verifies that the listing endpoint correctly filters posts by both
 * topic ID and author_member_id. The process ensures that only posts created
 * under a specific topic by a specific author are returned.
 *
 * Steps:
 *
 * 1. Create 3 user profiles using the admin endpoint.
 * 2. Assign all user profiles as members using the admin endpoint.
 * 3. Create 2 categories.
 * 4. Each member creates a topic in a category.
 * 5. All members create posts in all topics (generating a uniform post matrix).
 * 6. Add extra posts by one member under one topic for robust filter testing.
 * 7. Call the post list endpoint with discussion_board_topic_id and
 *    author_member_id as filters.
 * 8. Assert that every result has both the filtered topic and author values, and
 *    that only expected posts are present.
 */
export async function test_api_discussion_board_test_list_posts_with_filters_on_topic_id_and_author(
  connection: api.IConnection,
) {
  // 1. Create 3 user profiles
  const profiles = await Promise.all([
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        is_active: true,
      },
    }),
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        is_active: true,
      },
    }),
    api.functional.admin.discussion_board.userProfiles.create(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        is_active: true,
      },
    }),
  ]);
  for (const profile of profiles) typia.assert(profile);

  // 2. Assign each profile as board member
  const now = new Date().toISOString();
  const members = await Promise.all(
    profiles.map((profile) =>
      api.functional.admin.discussion_board.members.create(connection, {
        body: {
          discussion_board_user_profile_id: profile.id,
          joined_at: now,
        },
      }),
    ),
  );
  for (const member of members) typia.assert(member);

  // 3. Create 2 board categories
  const categories = await Promise.all([
    api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph()(2),
        description: RandomGenerator.paragraph()(),
        sort_order: 1,
        is_active: true,
      },
    }),
    api.functional.admin.discussion_board.categories.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph()(2),
        description: RandomGenerator.paragraph()(),
        sort_order: 2,
        is_active: true,
      },
    }),
  ]);
  for (const category of categories) typia.assert(category);

  // 4. Each member creates a topic (round-robin distribute categories)
  const topics = await Promise.all(
    members.map((member, i) =>
      api.functional.my.discussion_board.topics.create(connection, {
        body: {
          discussion_board_category_id: categories[i % categories.length].id,
          title: RandomGenerator.paragraph()(),
          description: RandomGenerator.content()()(),
          status: "open",
        },
      }),
    ),
  );
  for (const topic of topics) typia.assert(topic);

  // 5. All members create posts in all topics
  const posts: IDiscussionBoardPost[] = [];
  for (const member of members) {
    for (const topic of topics) {
      // (Auth context is not actually switched per member in this test infra)
      const post = await api.functional.my.discussion_board.posts.create(
        connection,
        {
          body: {
            discussion_board_topic_id: topic.id,
            title: RandomGenerator.paragraph()(),
            body: RandomGenerator.content()()(),
          },
        },
      );
      typia.assert(post);
      posts.push(post);
    }
  }

  // 6. For filter test, pick a topic/member & add further posts for robustness
  const targetTopic = topics[0];
  const targetAuthor = members[1];
  const extraPosts: IDiscussionBoardPost[] = [];
  for (let i = 0; i < 2; ++i) {
    const post = await api.functional.my.discussion_board.posts.create(
      connection,
      {
        body: {
          discussion_board_topic_id: targetTopic.id,
          title: RandomGenerator.paragraph()(),
          body: RandomGenerator.content()()(),
        },
      },
    );
    typia.assert(post);
    extraPosts.push(post);
  }
  // Gather expected post IDs for this author & topic
  const expectedPostIDs = posts
    .filter(
      (p) =>
        p.discussion_board_topic_id === targetTopic.id &&
        p.author_member_id === targetAuthor.id,
    )
    .map((p) => p.id)
    .concat(extraPosts.map((p) => p.id));

  // 7. Query the post list endpoint with combined filters
  const output = await api.functional.discussion_board.posts.index(connection, {
    body: {
      discussion_board_topic_id: targetTopic.id,
      author_member_id: targetAuthor.id,
      page: 1,
      limit: 99,
    },
  });
  typia.assert(output);

  // 8. Validate the filtered posts
  for (const post of output.data) {
    TestValidator.equals("topic filtered")(post.discussion_board_topic_id)(
      targetTopic.id,
    );
    TestValidator.equals("author filtered")(post.author_member_id)(
      targetAuthor.id,
    );
    TestValidator.predicate("id in expected set")(
      expectedPostIDs.includes(post.id),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E Test: Search and filter posts by keyword in body or title.
 *
 * Business context: Forums require the ability to search posts for moderation,
 * discoverability, or audit. To validate post search, this test will:
 *
 * - Create multiple diverse posts with distinctive keywords in their bodies
 *   and/or titles.
 * - Use the post-listing API with a search keyword filter (body_keyword).
 * - Assert that only posts containing the keyword (in body or title) are returned
 *   and others are excluded.
 *
 * Steps:
 *
 * 1. Create several user profiles (with is_active true, different emails/names)
 *    for data diversity.
 * 2. Assign each user profile as a member (joined_at now).
 * 3. Create at least one active category (with a unique code)
 * 4. For each member, create a topic in the category with a unique title and
 *    description.
 * 5. For each member/topic, create multiple posts:
 *
 *    - At least one post per member with a test keyword (e.g.,
 *         'e2e-keyword-search-XYZ') in the title or body
 *    - At least one post per member without the keyword
 * 6. Call the /discussion_board/posts index API with body_keyword set to the
 *    keyword to filter.
 * 7. Assert that only the posts containing the keyword are returned, and all posts
 *    without it are excluded.
 * 8. Validate that pagination and result counts align with the injected dataset.
 */
export async function test_api_discussion_board_test_list_posts_with_keyword_search_in_body(
  connection: api.IConnection,
) {
  // 1. Create user profiles
  const userProfiles: IDiscussionBoardUserProfile[] =
    await ArrayUtil.asyncRepeat(3)(async () => {
      const input = {
        email: typia.random<string & tags.Format<"email">>(),
        display_name: RandomGenerator.name(),
        is_active: true,
      } satisfies IDiscussionBoardUserProfile.ICreate;
      const result =
        await api.functional.admin.discussion_board.userProfiles.create(
          connection,
          { body: input },
        );
      typia.assert(result);
      return result;
    });

  // 2. Assign user profiles as members
  const members: IDiscussionBoardMember[] = await ArrayUtil.asyncMap(
    userProfiles,
  )(async (user) => {
    const input = {
      discussion_board_user_profile_id: user.id,
      joined_at: new Date().toISOString(),
    } satisfies IDiscussionBoardMember.ICreate;
    const result = await api.functional.admin.discussion_board.members.create(
      connection,
      { body: input },
    );
    typia.assert(result);
    return result;
  });

  // 3. Create category
  const categoryInput = {
    code: `cat-${RandomGenerator.alphaNumeric(5)}`,
    name: RandomGenerator.name(),
    sort_order: 1,
    is_active: true,
  } satisfies IDiscussionBoardCategory.ICreate;
  const category =
    await api.functional.admin.discussion_board.categories.create(connection, {
      body: categoryInput,
    });
  typia.assert(category);

  // 4. Create topics (one per member)
  const topics: IDiscussionBoardTopic[] = await ArrayUtil.asyncMap(members)(
    async (member) => {
      const input = {
        discussion_board_category_id: category.id,
        title: RandomGenerator.paragraph()(),
        description: RandomGenerator.content()()(),
        status: "open",
      } satisfies IDiscussionBoardTopic.ICreate;
      const topic = await api.functional.my.discussion_board.topics.create(
        connection,
        { body: input },
      );
      typia.assert(topic);
      return topic;
    },
  );

  // 5. Create posts with and without keyword
  const searchKeyword = "e2e-keyword-search-7749";
  const postsWithKeyword: IDiscussionBoardPost[] = [];
  const postsWithoutKeyword: IDiscussionBoardPost[] = [];
  for (let i = 0; i < members.length; ++i) {
    // At least one post with the keyword (in title)
    {
      const input = {
        discussion_board_topic_id: topics[i].id,
        title: `${searchKeyword} Title Test`,
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate;
      const post = await api.functional.my.discussion_board.posts.create(
        connection,
        { body: input },
      );
      typia.assert(post);
      postsWithKeyword.push(post);
    }
    // At least one post without the keyword
    {
      const input = {
        discussion_board_topic_id: topics[i].id,
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate;
      const post = await api.functional.my.discussion_board.posts.create(
        connection,
        { body: input },
      );
      typia.assert(post);
      postsWithoutKeyword.push(post);
    }
    // At least one post with the keyword (in body)
    {
      const input = {
        discussion_board_topic_id: topics[i].id,
        title: RandomGenerator.paragraph()(),
        body: `${RandomGenerator.content()()()} ${searchKeyword}`,
      } satisfies IDiscussionBoardPost.ICreate;
      const post = await api.functional.my.discussion_board.posts.create(
        connection,
        { body: input },
      );
      typia.assert(post);
      postsWithKeyword.push(post);
    }
  }

  // 6. Call API with keyword filter
  const result = await api.functional.discussion_board.posts.index(connection, {
    body: {
      body_keyword: searchKeyword,
      limit: 100,
    } satisfies IDiscussionBoardPost.IRequest,
  });
  typia.assert(result);

  // 7. Assert only keyword-containing posts are returned
  const resultIds = result.data.map((post) => post.id);
  for (const post of postsWithKeyword) {
    TestValidator.predicate(`post with keyword returned - ${post.id}`)(
      resultIds.includes(post.id),
    );
  }
  for (const post of postsWithoutKeyword) {
    TestValidator.predicate(`post without keyword excluded - ${post.id}`)(
      !resultIds.includes(post.id),
    );
  }

  // 8. Pagination/result count check
  TestValidator.equals("number of search results")(result.data.length)(
    postsWithKeyword.length,
  );
}

