import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopic } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopic";

/**
 * Validate that a member can update their own topic with valid data.
 *
 * This comprehensive test simulates a real workflow in which:
 *
 * 1. An admin creates a user profile (simulating user onboarding).
 * 2. The user is assigned as a discussion board member (admin action).
 * 3. The member creates a new topic under their account.
 * 4. The member updates the topic's title and description fields.
 *
 * This test validates:
 *
 * - That the user profile and member assignment processes complete successfully.
 * - Topic creation as the member is properly attributed to them.
 * - Topic update with allowed fields (title, description) is accepted and
 *   reflected in the returned data.
 * - The last_edited_by_member_id field is set after editing.
 * - Only permitted fields (title, description) are changed; immutable fields
 *   remain unchanged.
 * - All data conforms to DTO types and business rules.
 *
 * Steps:
 *
 * 1. Create user profile via admin API (userProfile).
 * 2. Assign user profile as member (member).
 * 3. (Assumed: switch to member context.)
 * 4. Member creates a topic (topic).
 * 5. Member updates topic's title/description (updated).
 * 6. Assert updates took effect, last_edited_by_member_id present, immutable
 *    fields unchanged.
 */
export async function test_api_my_discussion_board_topics_test_update_own_topic_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Admin creates user profile
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userProfile);

  // 2. Admin assigns as member
  const joinedAt = new Date().toISOString();
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: joinedAt,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 3. (Assume now acting as/with member context)

  // 4. Member creates a topic
  const topicCreateInput = {
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(3),
    description: RandomGenerator.paragraph()(5),
    status: "open",
  } satisfies IDiscussionBoardTopic.ICreate;
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    { body: topicCreateInput },
  );
  typia.assert(topic);

  // 5. Member updates their topic (title and description)
  const newTitle = RandomGenerator.paragraph()(4);
  const newDescription = RandomGenerator.paragraph()(6);
  const updateInput = {
    title: newTitle,
    description: newDescription,
  } satisfies IDiscussionBoardTopic.IUpdate;
  const updated = await api.functional.my.discussion_board.topics.update(
    connection,
    {
      id: topic.id,
      body: updateInput,
    },
  );
  typia.assert(updated);

  // 6. Validate updates took effect and audit fields are set
  TestValidator.equals("updated title")(updated.title)(newTitle);
  TestValidator.equals("updated description")(updated.description)(
    newDescription,
  );
  TestValidator.notEquals("last_edited_by_member_id set")(
    updated.last_edited_by_member_id,
  )(null);
  TestValidator.equals("topic id unchanged")(updated.id)(topic.id);
  TestValidator.equals("author not changed")(updated.created_by_member_id)(
    topic.created_by_member_id,
  );
  TestValidator.equals("category id immutable")(
    updated.discussion_board_category_id,
  )(topic.discussion_board_category_id);
  TestValidator.equals("status remains default unless changed")(updated.status)(
    topic.status,
  );
}

