 *
 * - It rejects payloads containing properties not defined in the update DTO (e.g.
 *   immutable keys)
 * - It rejects payloads that omit all updatable fields (empty body scenario) This
 *   covers schema-level and business logic validation ensuring only permissible
 *   updates are accepted.
 *
 * Steps:
 *
 * 1. Admin creates a user profile.
 * 2. Admin assigns this user profile as a board member.
 * 3. The new member creates a topic.
 * 4. Attempt to update the topic with a forbidden/invalid property in payload
 *    (e.g., 'id'); verify validation error.
 * 5. Attempt to update the topic with an empty payload; verify validation error.
 */
export async function test_api_my_discussion_board_topics_test_update_own_topic_with_invalid_fields(
  connection: api.IConnection,
) {
