  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userProfile);

  // 2. Admin assigns this user profile as a board member.
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

