  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: RandomGenerator.paragraph()(),
        description: RandomGenerator.content()()(),
        status: "open",
      } satisfies IDiscussionBoardTopic.ICreate,
    },
  );
  typia.assert(topic);

  // 4. Attempt update with forbidden field (e.g., 'id') in payload
  await TestValidator.error("should reject forbidden field in update payload")(
    async () => {
      await api.functional.my.discussion_board.topics.update(connection, {
        id: topic.id,
        // TypeScript will block this, but for negative-path testing we force the property at runtime
        body: { id: topic.id } as any,
      });
