  // 4. Switch authentication to non-owner member
  // (In actual e2e: switch to non-owner's session here.)

  // 5. Non-owner attempts to update the owner's topic; must fail
  await TestValidator.error("Non-owner cannot update another member's topic")(
    async () => {
      await api.functional.my.discussion_board.topics.update(connection, {
