 * 6. Validate that:
 *
 *    - All topic edit versions are present as snapshots
 *    - Snapshots reflect the correct editor/member for each update
 *    - Pagination fields are populated correctly in the response
 *    - Audit/history retention logic is working (history is not lost across updates)
 *
 * This tests the complete version/audit history retention for a topic, and
 * ensures that the snapshot listing endpoint returns all relevant information
 * filtered correctly.
 */
export async function test_api_discussion_board_test_list_topic_snapshots_for_existing_topic(
  connection: api.IConnection,
) {
  // 1. Create a user profile (admin API)
  const profileInput: IDiscussionBoardUserProfile.ICreate = {
    email: typia.random<string & tags.Format<"email">>(),
