      connection,
      {
        body: profileInput,
      },
    );
  typia.assert(userProfile);

  // 2. Assign member role to the profile (admin API)
  const memberInput: IDiscussionBoardMember.ICreate = {
    discussion_board_user_profile_id: userProfile.id,
    joined_at: new Date().toISOString(),
  };
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: memberInput,
    },
  );
  typia.assert(member);

  // 3. As this member, create a new topic (simulate login/impersonation if needed)
  // Since only the owner can create topics, assume the connection context does this.
  const topicInput: IDiscussionBoardTopic.ICreate = {
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(8),
    description: RandomGenerator.content()()(16),
    status: "open",
  };
  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: topicInput,
    },
  );
  typia.assert(topic);

