  const update1: IDiscussionBoardTopic.IUpdate = {
    title: RandomGenerator.paragraph()(8),
  };
  const updatedTopic1 = await api.functional.my.discussion_board.topics.update(
    connection,
    {
      id: topic.id,
      body: update1,
    },
