  // 5. List topic snapshots by topic id (all snapshots for this topic)
  const pageLimit = 5;
  const snapshotsPage =
    await api.functional.discussion_board.topicSnapshots.index(connection, {
      body: {
        discussion_board_topic_id: topic.id,
        page: 1,
        limit: pageLimit,
      },
    });
