  // 6. Validation:
  // - There should be at least three snapshots (initial + 2 updates)
  TestValidator.predicate("at least 3 snapshots exist for this topic")(
    snapshotsPage.data.length >= 3,
  );
  // - Snapshots should be for the given topic
  snapshotsPage.data.forEach((snap) => {
    TestValidator.equals("correct topic id in snapshot")(
      snap.discussion_board_topic_id,
    )(topic.id);
