    await api.functional.discussion_board.topicSnapshots.index(connection, {
      body: {
        discussion_board_topic_id: topic.id,
        edited_by_member_id: member.id,
        limit: pageLimit,
      },
    });
  typia.assert(editorSnapshots);
  editorSnapshots.data.forEach((snap) => {
    TestValidator.equals("edited by member matches fetch filter")(
      snap.edited_by_member_id,
    )(member.id);
    TestValidator.equals("snapshot topic matches fetch filter")(
      snap.discussion_board_topic_id,
    )(topic.id);
  });

  // - Pagination metadata should be populated
  TestValidator.equals("page number is 1")(snapshotsPage.pagination.current)(1);
  TestValidator.equals("limit matches")(snapshotsPage.pagination.limit)(
    pageLimit,
  );
}

