/**
 * Validate retrieval of a discussion topic snapshot by valid ID.
 *
 * This scenario simulates admin-driven and member-driven flows to ensure topic
 * audit trails work end-to-end:
 *
 * 1. Admin creates a user profile (member/editor).
 * 2. Admin assigns the profile as a board member.
 * 3. Member creates a topic (using their privileges).
 * 4. Member edits the topic several times, producing multiple snapshots.
 * 5. Fetch the snapshot list (using the topic id as filter); select a valid
 *    snapshot id.
 * 6. Retrieve the snapshot by id.
 * 7. Validate snapshot details: accuracy of edit metadata, links to topic and
 *    editor/member.
 */
export async function test_api_discussion_board_test_get_topic_snapshot_by_valid_id(
  connection: api.IConnection,
) {
  // 1. Admin creates a user profile (member/editor).
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
          registered_at: new Date().toISOString(),
        },
      },
    );
  typia.assert(userProfile);

  // 2. Admin assigns the user profile as a board member.
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(member);

  // 3. Member creates a topic.
  // For this test, use a dummy category UUID as required by the API contract. In live tests, this would be looked up.
  const discussion_board_category_id = typia.random<
    string & tags.Format<"uuid">
  >();
  const initialTitle = `Initial Title ${RandomGenerator.alphabets(6)}`;
  const initialDescription = `Initial Description ${RandomGenerator.paragraph()()}`;
  const status = "open";

  const topic = await api.functional.my.discussion_board.topics.create(
    connection,
    {
      body: {
        discussion_board_category_id,
        title: initialTitle,
        description: initialDescription,
        status,
        pinned_at: null,
        closed_at: null,
      },
    },
  );
  typia.assert(topic);

  // 4. Member makes multiple edits to the topic (at least two edits for snapshot depth).
  const edit1Title = `Edit1 Title ${RandomGenerator.alphabets(6)}`;
  const edit1Description = `Edit1 Desc ${RandomGenerator.paragraph()()}`;
  const updated1 = await api.functional.my.discussion_board.topics.update(
    connection,
    {
      id: topic.id,
      body: {
        title: edit1Title,
        description: edit1Description,
        status,
      },
    },
  );
  typia.assert(updated1);

  const edit2Title = `Edit2 Title ${RandomGenerator.alphabets(6)}`;
  const edit2Description = `Edit2 Desc ${RandomGenerator.paragraph()()}`;
  const updated2 = await api.functional.my.discussion_board.topics.update(
    connection,
    {
      id: topic.id,
      body: {
        title: edit2Title,
        description: edit2Description,
        status,
      },
    },
