import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing of topic subscriptions by member id with correct pagination
 * and relationships.
 *
 * This test ensures that when a member is subscribed to multiple topics,
 * filtering the topicSubscriptions endpoint by the member's id yields all of
 * their subscriptions. The test also checks the returned data structure,
 * validates paginated results, and confirms relationships
 * (notification/indexing integrity is inferred by returned properties).
 *
 * Steps:
 *
 * 1. Create a user profile (admin)
 * 2. Assign the user profile as a member (admin)
 * 3. Create several topics as a member
 * 4. Subscribe the member to each topic
 * 5. Request a list of topic subscriptions filtered by member id, with a specific
 *    pagination limit
 * 6. Assert that all expected subscriptions are present in the response
 * 7. Assert that the response contains proper pagination info and references
 * 8. (Implicit) The subscription records carry member_id/topic_id for further
 *    notification logic
 */
export async function test_api_discussion_board_test_list_topic_subscriptions_by_member_id(
  connection: api.IConnection,
) {
  // 1. Create a user profile
  const userProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(userProfile);

  // 2. Assign that profile as a board member
  const member = await api.functional.admin.discussion_board.members.create(
    connection,
    {
      body: {
        discussion_board_user_profile_id: userProfile.id,
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 3. Create several topics as the member (simulate role, but API requires only member assignment)
  const topicCount = 3;
  const topicIds: (string & tags.Format<"uuid">)[] = [];
  for (let i = 0; i < topicCount; ++i) {
    const topic = await api.functional.my.discussion_board.topics.create(
      connection,
      {
        body: {
          discussion_board_category_id: typia.random<
            string & tags.Format<"uuid">
          >(), // Assume a mock or existing category for test
          title: `Topic ${i + 1} (${RandomGenerator.paragraph()(1)})`,
          description: RandomGenerator.content()()(),
          status: "open",
        } satisfies IDiscussionBoardTopic.ICreate,
      },
    );
    typia.assert(topic);
    topicIds.push(topic.id);
  }

  // 4. Subscribe to all topics
  const subscriptions = [];
  for (const topicId of topicIds) {
    const subscription =
      await api.functional.my.discussion_board.topicSubscriptions.create(
        connection,
        {
          body: {
            discussion_board_topic_id: topicId,
          } satisfies IDiscussionBoardTopicSubscription.ICreate,
        },
      );
    typia.assert(subscription);
    subscriptions.push(subscription);
  }

  // 5. List topic subscriptions filtered by member id with pagination (limit = 2)
  const listPage1 =
    await api.functional.discussion_board.topicSubscriptions.index(connection, {
      body: {
        member_id: member.id,
        limit: 2,
        page: 1,
      } satisfies IDiscussionBoardTopicSubscription.IRequest,
    });
  typia.assert(listPage1);
  TestValidator.equals("limited subscriptions returned")(listPage1.data.length)(
    2,
  );
  TestValidator.equals("pagination page 1")(listPage1.pagination.current)(1);
  TestValidator.equals("pagination limit")(listPage1.pagination.limit)(2);
  // 6. Fetch page 2
  const listPage2 =
    await api.functional.discussion_board.topicSubscriptions.index(connection, {
      body: {
        member_id: member.id,
        limit: 2,
        page: 2,
      } satisfies IDiscussionBoardTopicSubscription.IRequest,
    });
  typia.assert(listPage2);
  TestValidator.equals("pagination page 2")(listPage2.pagination.current)(2);
  // 7. Aggregate and check for all subscriptions
  const aggregated = [...listPage1.data, ...listPage2.data];
  for (const expected of subscriptions) {
    const found = aggregated.find((s) => s.id === expected.id);
    TestValidator.predicate(`subscription returned: ${expected.id}`)(!!found);
    TestValidator.equals("member_id match")(found?.member_id)(member.id);
  }
  TestValidator.equals("should have all subscriptions")(aggregated.length)(
    subscriptions.length,
  );
  // 8. Validate returned record structure
  for (const record of aggregated) {
    TestValidator.equals("member_id matches")(record.member_id)(member.id);
    TestValidator.predicate("topic id was subscribed")(
      topicIds.includes(record.discussion_board_topic_id),
    );
    // Notification/indexing logic is implicit in these relationships
  }
}

