/**
 * Validate filtered and paginated retrieval of reports from the
 * discussion_board_reports table.
 *
 * This test checks the /discussion_board/reports PATCH endpoint, ensuring that
 * all supported filters, pagination, and search/sort options (as defined in
 * IRequest) work as expected. The workflow includes:
 *
 * 1. Creating diverse reports via /my/discussion_board/reports so report data
 *    covers various reporter_id, reported_entity_type, reason_id, description,
 *    and created_at span.
 * 2. For each filter (reporter_id, resolved status, reported_entity_type,
 *    reason_id, created_at_from, created_at_to), call the index API with that
 *    filter and verify only relevant reports are returned.
 * 3. Test pagination: request different page/limit combos and check correct
 *    slicing of data with pagination metadata.
 * 4. Test description filtering using a report reason keyword present in
 *    description (only simulated here: schema does not allow direct search by
 *    description).
 * 5. For filter values that match no data, assert the returned list is empty.
 *
 * Rationale: Ensures moderators and admins receive accurate
 * filtered/sorted/paginated report data for review flows and that business
 * filtering logic matches requirements. Validates correct empty-state behavior
 * for no-match queries.
 */
export async function test_api_discussion_board_test_list_reports_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create test data: several reports with varying reason_id, reported_entity_type
  const baseTime = new Date();
  const reportEntities = ArrayUtil.repeat(3)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  const reasonIds = ArrayUtil.repeat(2)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );

  // We'll simulate three different users by alternating reporter_id (realistically, connection user only but ids will still be unique)
  const reports: IDiscussionBoardReport[] = [];
  for (let i = 0; i < 4; ++i) {
    const report = await api.functional.my.discussion_board.reports.create(
      connection,
      {
        body: {
          reason_id: reasonIds[i % reasonIds.length],
          reported_entity_id: reportEntities[i % reportEntities.length],
          reported_entity_type: i % 2 === 0 ? "post" : "comment",
          description:
            i % 2 === 0 ? `test-description-keyword-${i}` : undefined,
        } satisfies IDiscussionBoardReport.ICreate,
      },
    );
    typia.assert(report);
    reports.push(report);
  }

  // 2. Filter: by reporter_id (from created reports)
  const filterByReporter = await api.functional.discussion_board.reports.index(
    connection,
    {
      body: {
        reporter_id: reports[0].reporter_id,
      } satisfies IDiscussionBoardReport.IRequest,
    },
  );
  typia.assert(filterByReporter);
  TestValidator.predicate(
    "filtered by reporter_id include only correct reporter",
  )(
    filterByReporter.data.every(
      (r) => r.reporter_id === reports[0].reporter_id,
    ),
  );

  // 3. Filter: by resolved status (should be false initially)
  const unresolved = await api.functional.discussion_board.reports.index(
    connection,
    {
      body: { resolved: false } satisfies IDiscussionBoardReport.IRequest,
    },
  );
  typia.assert(unresolved);
  TestValidator.predicate("all unresolved reports returned")(
    unresolved.data.every((r) => r.resolved === false),
  );

  // 4. Filter: by reported_entity_type
  const byEntityType = await api.functional.discussion_board.reports.index(
    connection,
    {
      body: {
        reported_entity_type: "post",
      } satisfies IDiscussionBoardReport.IRequest,
    },
  );
  typia.assert(byEntityType);
  TestValidator.predicate("all reports are for post type")(
    byEntityType.data.every((r) => r.reported_entity_type === "post"),
  );

  // 5. Filter: by reason_id
  const byReason = await api.functional.discussion_board.reports.index(
    connection,
    {
      body: {
        reason_id: reasonIds[0],
      } satisfies IDiscussionBoardReport.IRequest,
    },
  );
  typia.assert(byReason);
  TestValidator.predicate("all reports have correct reason_id")(
    byReason.data.every((r) => r.reason_id === reasonIds[0]),
  );

  // 6. Filter: by created_at_from/created_at_to (should span all new reports)
  const fromDate = new Date(Date.now() - 1000 * 60 * 10).toISOString();
  const toDate = new Date(Date.now() + 1000 * 60 * 10).toISOString();
  const byCreatedAt = await api.functional.discussion_board.reports.index(
    connection,
    {
      body: {
        created_at_from: fromDate,
        created_at_to: toDate,
      } satisfies IDiscussionBoardReport.IRequest,
    },
  );
  typia.assert(byCreatedAt);
  TestValidator.predicate("all reports in date range")(
    byCreatedAt.data.every(
      (r) => r.created_at >= fromDate && r.created_at <= toDate,
    ),
  );

  // 7. Pagination test: limit 2, page 1
  const paginated1 = await api.functional.discussion_board.reports.index(
    connection,
    {
      body: { limit: 2, page: 1 } satisfies IDiscussionBoardReport.IRequest,
    },
  );
  typia.assert(paginated1);
  TestValidator.equals("pagination limit 2")(paginated1.pagination.limit)(2);
  TestValidator.equals("pagination page 1")(paginated1.pagination.current)(1);

  // 8. Pagination test: limit 2, page 2
  const paginated2 = await api.functional.discussion_board.reports.index(
    connection,
    {
      body: { limit: 2, page: 2 } satisfies IDiscussionBoardReport.IRequest,
    },
  );
  typia.assert(paginated2);
  TestValidator.equals("pagination page 2")(paginated2.pagination.current)(2);

  // 9. (Simulated) description filter: schema does not support, but description is in data for future extensibility
  // 10. Edge: filter to no results
  const emptyResult = await api.functional.discussion_board.reports.index(
    connection,
    {
      body: {
        reporter_id: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IDiscussionBoardReport.IRequest,
    },
  );
  typia.assert(emptyResult);
  TestValidator.equals("no reports for random reporter")(
    emptyResult.data.length,
  )(0);
}

