  TestValidator.equals("reason_id matches")(report.reason_id)(reportReason.id);
  TestValidator.equals("reported_entity_id matches")(report.reported_entity_id)(
    post.id,
  );
  TestValidator.equals("reported_entity_type is post")(
    report.reported_entity_type,
  )("post");
  TestValidator.equals("description matches")(report.description)(description);
  TestValidator.equals("resolved defaults to false")(report.resolved)(false);
  TestValidator.predicate("id exists and is uuid")(
    typeof report.id === "string" && report.id.length > 0,
  );
  TestValidator.predicate("created_at exists")(
    typeof report.created_at === "string" && report.created_at.length > 0,
  );
  TestValidator.predicate("reporter_id exists")(
    typeof report.reporter_id === "string" && report.reporter_id.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
