 * 1. Admin creates a new discussion board user profile to establish an
 *    authenticated context.
 * 2. Submit a report missing `reason_id` (should error).
 * 3. Submit a report missing `reported_entity_id` (should error).
 * 4. Submit a report with an invalid (non-uuid) `reason_id` (should error).
 * 5. Submit a report with an invalid (non-uuid) `reported_entity_id` (should
 *    error).
 */
export async function test_api_my_discussion_board_reports_test_create_report_with_missing_required_fields(
  connection: api.IConnection,
) {
