          email: typia.random<string & tags.Format<"email">>(),
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(memberProfile);

  // 2. Attempt: missing reason_id
  await TestValidator.error("missing reason_id should fail")(async () => {
    await api.functional.my.discussion_board.reports.create(connection, {
      body: {
        // reason_id intentionally omitted
        reported_entity_id: typia.random<string & tags.Format<"uuid">>(),
        reported_entity_type: "post",
      } as any, // only for negative case, okay here
    });
  });

  // 3. Attempt: missing reported_entity_id
  await TestValidator.error("missing reported_entity_id should fail")(
    async () => {
      await api.functional.my.discussion_board.reports.create(connection, {
        body: {
          reason_id: typia.random<string & tags.Format<"uuid">>(),
          // reported_entity_id intentionally omitted
          reported_entity_type: "comment",
        } as any,
      });
    },
  );

  // 4. Attempt: invalid reason_id (not a uuid)
  await TestValidator.error("invalid reason_id format should fail")(
    async () => {
      await api.functional.my.discussion_board.reports.create(connection, {
        body: {
          reason_id: "not-a-uuid",
          reported_entity_id: typia.random<string & tags.Format<"uuid">>(),
          reported_entity_type: "user",
        } satisfies IDiscussionBoardReport.ICreate,
      });
    },
  );

  // 5. Attempt: invalid reported_entity_id (not a uuid)
  await TestValidator.error("invalid reported_entity_id format should fail")(
    async () => {
      await api.functional.my.discussion_board.reports.create(connection, {
        body: {
          reason_id: typia.random<string & tags.Format<"uuid">>(),
          reported_entity_id: "not-a-uuid",
          reported_entity_type: "user",
        } satisfies IDiscussionBoardReport.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardUserProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardUserProfile";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IDiscussionBoardReportReason } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReportReason";

/**
 * Validate the behavior of creating duplicate reports on the same entity by the
 * same user for the same reason.
 *
 * This test ensures that if a member submits a report regarding a post, and
 * then attempts to submit another report against that same post with the same
 * reason (and same details), the system should either prevent the duplicate or
 * otherwise enforce business rules — such as allowing only one active report
 * per (user, entity, reason) tuple.
 *
 * Steps:
 *
 * 1. Admin creates and activates a standardized report reason.
 * 2. Admin creates an active member profile (who will act as the reporter).
 * 3. The test logs in (using test infrastructure) as that member (assume profile
 *    creation provides context for authentication).
 * 4. The member creates a new post (target entity for the report) using
 *    /my/discussion_board/posts.
 * 5. The member submits a report against the post, using the previously created
 *    reason.
 * 6. The member immediately attempts to submit another report with the same reason
 *    for the same entity.
 * 7. The test asserts that the system either prevents the duplicate, or only
 *    allows a single active report per user/entity/reason (i.e., throws an
 *    error or otherwise enforces the uniqueness/business rule).
 */
export async function test_api_my_discussion_board_reports_test_create_duplicate_report_on_same_entity_from_same_user(
  connection: api.IConnection,
) {
  // 1. Admin creates a standardized report reason.
  const reportReason =
    await api.functional.admin.discussion_board.reportReasons.create(
      connection,
      {
        body: {
          reason_text: RandomGenerator.paragraph()(3),
          active: true,
        } satisfies IDiscussionBoardReportReason.ICreate,
      },
    );
  typia.assert(reportReason);

  // 2. Admin creates a user profile for the reporting member.
  const testEmail = typia.random<string & tags.Format<"email">>();
  const memberProfile =
    await api.functional.admin.discussion_board.userProfiles.create(
      connection,
      {
        body: {
          email: testEmail,
          display_name: RandomGenerator.name(),
          is_active: true,
        } satisfies IDiscussionBoardUserProfile.ICreate,
      },
    );
  typia.assert(memberProfile);

  // [Assume authentication context is managed and profile creation confers proper context for subsequent member-auth API calls]

  // 3. Member creates a new discussion board post (reportable entity)
  const post = await api.functional.my.discussion_board.posts.create(
    connection,
    {
      body: {
        discussion_board_topic_id: typia.random<string & tags.Format<"uuid">>(),
        title: RandomGenerator.paragraph()(),
        body: RandomGenerator.content()()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 4. Member submits a report against the post
  const reportBody: IDiscussionBoardReport.ICreate = {
    reason_id: reportReason.id,
    reported_entity_id: post.id,
    reported_entity_type: "post",
    description: RandomGenerator.paragraph()(),
  };
  const report = await api.functional.my.discussion_board.reports.create(
    connection,
    {
      body: reportBody,
    },
  );
  typia.assert(report);

  // 5. Attempt duplicate report (same user, entity, and reason)
  await TestValidator.error(
    "Should not allow duplicate report by same member for same entity and reason",
  )(async () => {
    await api.functional.my.discussion_board.reports.create(connection, {
      body: reportBody,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Validate that an admin can resolve a previously submitted report and add
 * moderation notes.
 *
 * This test mimics the realistic admin moderation workflow for content report
 * resolution.
 *
 * Step-by-step scenario:
 *
 * 1. Create a new discussion board report (as a normal member) which is initially
 *    unresolved (resolved=false)
 * 2. Update this report as an admin using the admin endpoint:
 *
 *    - Set 'resolved' to true
 *    - Add (or update) the 'description'/moderation notes
 * 3. Fetch the result and verify:
 *
 *    - The resolved status is now true
 *    - The moderation notes/description has been updated correctly
 *    - The report id and other fields are unchanged except as expected
 */
export async function test_api_admin_discussion_board_reports_test_admin_resolve_report_with_valid_update(
  connection: api.IConnection,
) {
  // 1. Member creates a new unresolved report
  const createPayload: IDiscussionBoardReport.ICreate = {
    reason_id: typia.random<string & tags.Format<"uuid">>(),
    reported_entity_id: typia.random<string & tags.Format<"uuid">>(),
    reported_entity_type: "post",
    description: "Initial user report description.",
  };
  const report: IDiscussionBoardReport =
    await api.functional.my.discussion_board.reports.create(connection, {
      body: createPayload,
    });
  typia.assert(report);
  TestValidator.equals("report initially unresolved")(report.resolved)(false);

  // 2. Admin resolves the report with a new moderation note
  const updatePayload: IDiscussionBoardReport.IUpdate = {
    resolved: true,
    description: "Moderation review completed. Content did violate rules.",
  };
  const updated: IDiscussionBoardReport =
    await api.functional.admin.discussion_board.reports.update(connection, {
      id: report.id,
      body: updatePayload,
    });
  typia.assert(updated);

  // 3. Assertion of correct changes
  TestValidator.equals("status resolved")(updated.resolved)(true);
  TestValidator.equals("moderation note updated")(updated.description)(
    updatePayload.description,
  );
  TestValidator.equals("id unchanged")(updated.id)(report.id);
  TestValidator.equals("entity id unchanged")(updated.reported_entity_id)(
    report.reported_entity_id,
  );
  TestValidator.equals("entity type unchanged")(updated.reported_entity_type)(
    report.reported_entity_type,
  );
  TestValidator.equals("reason unchanged")(updated.reason_id)(report.reason_id);
}

